  // ─── Draft Agreement: interview pane ─────────────────────────────
  // Conversational Q&A. Each turn = an agent question + the user's
  // answer. After 3-5 turns the agent decides intake is sufficient
  // and offers a "Generate Draft" button.
  function _bodyInterview() {
    var iv = _egActive.interview || {};
    var turns = iv.turns || [];
    var seed = iv.seed || "";
    var turnsHtml = (seed ? '<div class="_eg_iv_turn _eg_iv_user"><div class="_eg_iv_role">YOU</div><div class="_eg_iv_text">' + _esc(seed) + '</div></div>' : "") +
      turns.map(function (t) {
        var qHtml = '<div class="_eg_iv_turn _eg_iv_agent"><div class="_eg_iv_role">📝 AGENT</div><div class="_eg_iv_text">' + _esc(t.question || "") + '</div></div>';
        var aHtml = '';
        if (t.answer) {
          aHtml = '<div class="_eg_iv_turn _eg_iv_user"><div class="_eg_iv_role">YOU</div><div class="_eg_iv_text">' + _esc(t.answer) + '</div></div>';
        }
        return qHtml + aHtml;
      }).join("");
    // The pending agent question (waiting for user answer).
    var pending = iv.nextQuestions && iv.nextQuestions.length ? iv.nextQuestions[0] : null;
    var inputArea = "";
    if (pending) {
      var qHtml = '<div class="_eg_iv_turn _eg_iv_agent"><div class="_eg_iv_role">📝 AGENT</div><div class="_eg_iv_text">' + _esc(pending.question || "") + '</div></div>';
      // Render input based on question type.
      if (pending.type === "choice" && Array.isArray(pending.options) && pending.options.length) {
        inputArea = qHtml +
          '<div class="_eg_iv_choices">' +
            pending.options.map(function (o) {
              return '<button type="button" class="_eg_btn_secondary _eg_iv_choice_btn" data-eg-iv-choice="' + _esc(o) + '">' + _esc(o) + '</button>';
            }).join("") +
          '</div>' +
          '<div class="_eg_iv_input_row">' +
            '<input id="_eg_iv_text_input" type="text" class="_eg_iv_text_input" placeholder="…or type a custom answer" />' +
            '<button id="_eg_iv_submit" type="button" class="_eg_btn_primary">Send</button>' +
          '</div>';
      } else {
        inputArea = qHtml +
          '<div class="_eg_iv_input_row">' +
            '<input id="_eg_iv_text_input" type="text" class="_eg_iv_text_input" placeholder="Type your answer…" autofocus />' +
            '<button id="_eg_iv_submit" type="button" class="_eg_btn_primary">Send</button>' +
          '</div>';
      }
    } else if (!iv.intakeComplete && !turns.length && !iv.nextQuestions) {
      // Initial state — kick off the first agent question.
      inputArea = '<div class="_eg_status_box"><div class="_eg_status_dot"></div><div>Preparing first intake question…</div></div>';
    } else if (iv.intakeComplete) {
      // Ready to draft.
      inputArea = '<div class="_eg_actions_row _eg_actions_sticky">' +
        '<button id="_eg_iv_more" type="button" class="_eg_btn_secondary">Add more context</button>' +
        '<button id="_eg_iv_draft" type="button" class="_eg_btn_primary _eg_btn_apply">Generate Draft →</button>' +
      '</div>';
    }
    return _bodyHeader() +
      '<div class="_eg_iv_thread">' + turnsHtml + '</div>' +
      inputArea;
  }
  function _wireInterviewControls(body) {
    // First time: kick off the interview if no questions yet.
    var iv = _egActive.interview;
    if (!iv.turns.length && !iv.nextQuestions && !iv.intakeComplete) {
      _runInterviewTurn("");  // initial — no answer to process
      return;
    }
    // Choice buttons.
    body.querySelectorAll("[data-eg-iv-choice]").forEach(function (btn) {
      btn.onclick = function () {
        var answer = btn.getAttribute("data-eg-iv-choice");
        _submitInterviewAnswer(answer);
      };
    });
    // Free-text input + Send.
    var textInput = body.querySelector("#_eg_iv_text_input");
    var sendBtn = body.querySelector("#_eg_iv_submit");
    if (sendBtn) sendBtn.onclick = function () {
      var v = textInput ? (textInput.value || "").trim() : "";
      if (!v) return;
      _submitInterviewAnswer(v);
    };
    if (textInput) {
      textInput.onkeydown = function (e) {
        if (e.key === "Enter") { e.preventDefault(); if (sendBtn) sendBtn.click(); }
      };
      try { textInput.focus(); } catch (_) {}
    }
    // Post-intake actions.
    var draftBtn = body.querySelector("#_eg_iv_draft");
    if (draftBtn) draftBtn.onclick = function () { _runDraftPipeline(); };
    var moreBtn = body.querySelector("#_eg_iv_more");
    if (moreBtn) moreBtn.onclick = function () {
      _egActive.interview.intakeComplete = false;
      _runInterviewTurn(null);  // ask another question
    };
  }
  function _submitInterviewAnswer(answer) {
    var iv = _egActive.interview;
    var pending = iv.nextQuestions && iv.nextQuestions[0];
    if (!pending) return;
    iv.turns.push({ question: pending.question, answer: String(answer), type: pending.type || "text" });
    iv.nextQuestions = iv.nextQuestions.slice(1);
    _renderOverlayBody();
    if (!iv.nextQuestions.length) {
      _runInterviewTurn(answer);  // get next question(s) from agent
    }
  }
  // Ask the AI for the next intake question (or signal intake is done).
  function _runInterviewTurn(lastAnswer) {
    if (!_egActive) return;
    var prompt = _buildInterviewTurnPrompt(_egActive, lastAnswer);
    _aiJsonCall(prompt, { intakeComplete: "boolean", questions: "object", agreementType: "string" })
      .then(function (result) {
        if (!_egActive) return;
        if (result && result.intakeComplete) {
          _egActive.interview.intakeComplete = true;
          _egActive.interview.nextQuestions = null;
          if (result.agreementType) _egActive.interview.agreementType = result.agreementType;
        } else if (result && Array.isArray(result.questions) && result.questions.length) {
          _egActive.interview.nextQuestions = result.questions;
          if (result.agreementType && !_egActive.interview.agreementType) {
            _egActive.interview.agreementType = result.agreementType;
          }
        } else {
          // Empty result — treat as intake complete to avoid getting stuck.
          _egActive.interview.intakeComplete = true;
        }
        _renderOverlayBody();
      })
      .catch(function (err) {
        _egActive.status = "error";
        _egActive.error = (err && err.message) || String(err);
        _renderOverlayBody();
      });
  }

  // ─── Draft Agreement: outline review ─────────────────────────────
  function _bodyOutline() {
    var sections = (_egActive.outline || []);
    var rows = sections.map(function (s) {
      return '<div class="_eg_outline_row">' +
        '<span class="_eg_outline_num">§' + _esc(String(s.num || "?")) + '</span>' +
        '<div>' +
          '<div class="_eg_outline_name">' + _esc(s.name || "") + '</div>' +
          '<div class="_eg_outline_focus">' + _esc(s.focus || "") + '</div>' +
        '</div>' +
      '</div>';
    }).join("");
    return _bodyHeader() +
      _stageStrip("buckets") +
      '<div class="_eg_section_label">PROPOSED OUTLINE (' + sections.length + ' sections)</div>' +
      '<div class="_eg_compose_hint">Review what I plan to draft, then continue.</div>' +
      rows +
      '<div class="_eg_actions_row _eg_actions_sticky">' +
        '<button id="_eg_outline_back" type="button" class="_eg_btn_secondary">← Back</button>' +
        '<button id="_eg_outline_proceed" type="button" class="_eg_btn_primary _eg_btn_apply">Draft Sections →</button>' +
      '</div>';
  }
  function _wireOutlineControls(body) {
    var backBtn = body.querySelector("#_eg_outline_back");
    if (backBtn) backBtn.onclick = function () {
      _egActive.status = "interview";
      _renderOverlayBody();
    };
    var proceedBtn = body.querySelector("#_eg_outline_proceed");
    if (proceedBtn) proceedBtn.onclick = _runSectionDrafting;
  }

  // ─── Draft Agreement: drafting progress + review ─────────────────
  function _bodyDrafting() {
    var sections = _egActive.outline || [];
    var rows = sections.map(function (s) {
      var icon = s.status === "done" ? "✓" : s.status === "failed" ? "⚠" : s.status === "drafting" ? "⚙" : "○";
      var cls = "_eg_bucket_row _eg_bucket_" + (s.status || "queued");
      return '<div class="' + cls + '">' +
        '<span class="_eg_bucket_icon">' + icon + '</span>' +
        '<div class="_eg_bucket_name">§' + _esc(String(s.num || "?")) + ' ' + _esc(s.name || "") + '</div>' +
        '<div class="_eg_bucket_focus">' + _esc(s.focus || "") + '</div>' +
        '<div class="_eg_bucket_count">' + (s.status === "done" ? "✓" : s.status === "failed" ? "failed" : "drafting…") + '</div>' +
      '</div>';
    }).join("");
    return _bodyHeader() +
      _stageStrip("buckets") +
      '<div class="_eg_section_label">DRAFTING (' + sections.filter(function(s){return s.status==="done";}).length + '/' + sections.length + ')</div>' +
      '<div class="_eg_bucket_list">' + rows + '</div>' +
      '<div class="_eg_actions_row">' +
        '<button id="_eg_cancel_plan" type="button" class="_eg_btn_secondary">Cancel</button>' +
      '</div>';
  }
  function _bodyDraftReview() {
    var sections = _egActive.outline || [];
    var rows = sections.map(function (s) {
      var status = _egActive.draftAcceptance[s.id] || "accept";
      var statusCls = "_eg_draft_section_" + status;
      var content = String(s.content || "(no content)");
      var preview = content.length > 800 ? content.slice(0, 800) + "…" : content;
      return '<div class="_eg_draft_section ' + statusCls + '" id="_eg_draft_' + _esc(s.id) + '">' +
        '<div class="_eg_draft_section_head">' +
          '<div class="_eg_draft_section_title">§' + _esc(String(s.num || "?")) + ' ' + _esc(s.name || "") + '</div>' +
          '<div class="_eg_draft_section_actions">' +
            '<button type="button" class="_eg_card_btn _eg_draft_regen" data-eg-draft-action="regen" data-eg-section-id="' + _esc(s.id) + '">🔄 Regenerate</button>' +
            '<button type="button" class="_eg_card_btn _eg_card_accept" data-eg-draft-action="accept" data-eg-section-id="' + _esc(s.id) + '"' + (status === "accept" ? ' disabled' : '') + '>✓ Include</button>' +
            '<button type="button" class="_eg_card_btn _eg_card_reject" data-eg-draft-action="skip" data-eg-section-id="' + _esc(s.id) + '"' + (status === "skip" ? ' disabled' : '') + '>✗ Skip</button>' +
          '</div>' +
        '</div>' +
        '<pre class="_eg_draft_preview">' + _esc(preview) + '</pre>' +
      '</div>';
    }).join("");
    var includedCount = sections.filter(function (s) { return (_egActive.draftAcceptance[s.id] || "accept") === "accept"; }).length;
    return _bodyHeader() +
      '<div class="_eg_summary">Generated ' + sections.length + ' sections. Review + skip any you don\'t want.</div>' +
      rows +
      '<div class="_eg_actions_row _eg_actions_sticky">' +
        '<button id="_eg_draft_new" type="button" class="_eg_btn_secondary">New Draft</button>' +
        '<button id="_eg_draft_insert" type="button" class="_eg_btn_primary _eg_btn_apply" ' + (includedCount ? '' : 'disabled') + '>Insert ' + includedCount + ' Section' + (includedCount === 1 ? "" : "s") + ' →</button>' +
      '</div>';
  }
  function _wireDraftReviewControls(body) {
    body.querySelectorAll("[data-eg-draft-action]").forEach(function (btn) {
      btn.onclick = function () {
        var action = btn.getAttribute("data-eg-draft-action");
        var id = btn.getAttribute("data-eg-section-id");
        if (action === "accept") _egActive.draftAcceptance[id] = "accept";
        else if (action === "skip") _egActive.draftAcceptance[id] = "skip";
        else if (action === "regen") { _regenerateDraftSection(id, btn); return; }
        _renderOverlayBody();
      };
    });
    var insertBtn = body.querySelector("#_eg_draft_insert");
    if (insertBtn) insertBtn.onclick = _insertAcceptedDraftSections;
    var newBtn = body.querySelector("#_eg_draft_new");
    if (newBtn) newBtn.onclick = function () {
      _egActive.interview = { seed: "", turns: [], nextQuestions: null, agreementType: null, intakeComplete: false };
      _egActive.outline = null;
      _egActive.draftAcceptance = {};
      _egActive.status = "interview";
      _renderOverlayBody();
    };
  }
  function _bodyInsertingDraft() {
    return _bodyHeader() +
      '<div class="_eg_status_box">' +
