    var closeBtn = body.querySelector("#_eg_close_done2");
    if (closeBtn) closeBtn.onclick = _closeAgentOverlay;
  }

  // ─── Review body — strategy + unrequested + cards + mini-map ──────
  function _bodyReview() {
    var plan = _egActive.plan || { summary: "", edits: [], unrequested: [], negotiationStrategy: null };
    var edits = plan.edits || [];
    if (!edits.length) {
      return _bodyHeader() +
        '<div class="_eg_empty_box">' +
          '<div class="_eg_empty_title">No edits proposed</div>' +
          '<div class="_eg_empty_msg">' + _esc(plan.summary || "I read the doc but didn't find anything to change for this brief. Try rephrasing or being more specific.") + '</div>' +
        '</div>' +
        _renderUnrequestedSection(plan.unrequested) +
        '<div class="_eg_actions_row">' +
          '<button id="_eg_replan" type="button" class="_eg_btn_secondary">Try again</button>' +
        '</div>';
    }
    // Group edits by section (or category if no section).
    var groups = {};
    var groupOrder = [];
    edits.forEach(function (e) {
      var key = e.section || e.category || "Other";
      if (!groups[key]) { groups[key] = []; groupOrder.push(key); }
      groups[key].push(e);
    });
    var counts = _editCounts();
    var cardsHtml = groupOrder.map(function (g) {
      return '<div class="_eg_group">' +
        '<div class="_eg_group_header">' + _esc(g) + ' <span class="_eg_group_count">(' + groups[g].length + ')</span></div>' +
        groups[g].map(function (e) { return _editCardHtml(e); }).join("") +
      '</div>';
    }).join("");
    return _bodyHeader() +
      '<div class="_eg_summary">' + _esc(plan.summary || "") + '</div>' +
      _renderNegotiationStrategySection(plan.negotiationStrategy, edits) +
      _renderUnrequestedSection(plan.unrequested) +
      '<div class="_eg_review_stats">' +
        '<span class="_eg_stat _eg_stat_total">' + counts.total + ' edits</span>' +
        '<span class="_eg_stat _eg_stat_accepted">' + counts.accepted + ' accepted</span>' +
        '<span class="_eg_stat _eg_stat_pending">' + counts.pending + ' pending</span>' +
        (counts.rejected ? '<span class="_eg_stat _eg_stat_rejected">' + counts.rejected + ' rejected</span>' : '') +
      '</div>' +
      '<div class="_eg_section_label">PROPOSED EDITS</div>' +
      '<div class="_eg_review_main">' +
        '<div class="_eg_cards_col">' + cardsHtml + '</div>' +
        _renderMiniMap(edits, groupOrder, groups) +
      '</div>' +
      '<div class="_eg_actions_row _eg_actions_sticky">' +
        '<button id="_eg_accept_all_high" type="button" class="_eg_btn_secondary">Accept All ●●●●○+</button>' +
        '<button id="_eg_accept_all" type="button" class="_eg_btn_secondary">Accept All</button>' +
        '<button id="_eg_apply" type="button" class="_eg_btn_primary _eg_btn_apply" ' + (counts.accepted ? '' : 'disabled') + '>' +
          'Apply ' + counts.accepted + ' to Doc' +
        '</button>' +
      '</div>';
  }
  // ─── Negotiation strategy section ─────────────────────────────────
  // Collapsible. Shows the AI's proposed presentation order (Round 1
  // / Round 2 / Round 3) + rationale. Defaults to expanded so the
  // user sees it without having to discover it.
  function _renderNegotiationStrategySection(strat, edits) {
    if (!strat || !Array.isArray(strat.rounds) || !strat.rounds.length) return "";
    var editById = {};
    edits.forEach(function (e) { editById[e.id] = e; });
    var roundsHtml = strat.rounds.map(function (r, i) {
      var label = r.name || ("Round " + (i + 1));
      var pillsHtml = (r.editIds || []).map(function (id) {
        var e = editById[id];
        if (!e) return "";
        return '<span class="_eg_strat_pill" data-eg-jump-edit="' + _esc(id) + '" title="' + _esc((e.section || e.category || "") + " — " + (e.rationale || "")) + '">' +
          _esc(e.section || e.category || id) +
        '</span>';
      }).join("");
      var why = r.why ? '<div class="_eg_strat_why">' + _esc(r.why) + '</div>' : '';
      return '<div class="_eg_strat_round">' +
        '<div class="_eg_strat_round_head">' + _esc(label) + '</div>' +
        why +
        '<div class="_eg_strat_pills">' + pillsHtml + '</div>' +
      '</div>';
    }).join("");
    return '<details class="_eg_strat_panel" open>' +
      '<summary class="_eg_strat_summary">🎯 Negotiation strategy — ' + strat.rounds.length + ' rounds</summary>' +
      (strat.rationale ? '<div class="_eg_strat_rationale">' + _esc(strat.rationale) + '</div>' : '') +
      roundsHtml +
    '</details>';
  }
  // ─── Unrequested findings (proactive surfacing) ───────────────────
  // Things the user didn't ask about but the AI noticed. Collapsible,
  // defaults to expanded so the user notices them. Each finding is an
  // info card with severity color band.
  function _renderUnrequestedSection(unrequested) {
    if (!Array.isArray(unrequested) || !unrequested.length) return "";
    var rows = unrequested.map(function (u) {
      var sev = u.severity === "high" ? "high" : u.severity === "low" ? "low" : "med";
      return '<div class="_eg_un_card _eg_un_' + sev + '">' +
        '<div class="_eg_un_head">' +
          '<span class="_eg_un_sev">' + (sev === "high" ? "🔴 HIGH" : sev === "low" ? "⚪ LOW" : "🟡 MED") + '</span>' +
          (u.section ? '<span class="_eg_un_section">' + _esc(u.section) + '</span>' : '') +
        '</div>' +
        '<div class="_eg_un_observation">' + _esc(u.observation || "") + '</div>' +
        (u.suggestedAction ? '<div class="_eg_un_action">→ ' + _esc(u.suggestedAction) + '</div>' : '') +
      '</div>';
    }).join("");
    return '<details class="_eg_un_panel" open>' +
      '<summary class="_eg_un_summary">💡 You didn\'t ask, but… (' + unrequested.length + ' finding' + (unrequested.length === 1 ? "" : "s") + ')</summary>' +
      rows +
    '</details>';
  }
  // ─── Mini-map sidebar ─────────────────────────────────────────────
  // Vertical strip on the right: one pin per edit, colored by status.
  // Hovering a pin scrolls + flashes its card. Pins are positioned
  // proportionally to the edit's paragraphIndex (or grouped if no idx).
  function _renderMiniMap(edits, groupOrder, groups) {
    var pinsHtml = '';
    edits.forEach(function (e) {
      var status = _egActive.acceptance[e.id] || "pending";
      var cls = "_eg_mm_pin _eg_mm_" + status;
      if (e.requiresHumanReview) cls += " _eg_mm_review";
      var pct = 50;
      if (e.paragraphIndex && e.paragraphTotal) {
        pct = Math.round((e.paragraphIndex / e.paragraphTotal) * 100);
      }
      var title = (e.section || e.category || "edit") + " · " + (e.confidence || 3) + "/5 confidence";
      pinsHtml += '<button type="button" class="' + cls + '" style="top:' + pct + '%;" ' +
        'data-eg-mm-pin="' + _esc(e.id) + '" title="' + _esc(title) + '"></button>';
    });
    return '<div class="_eg_minimap">' +
      '<div class="_eg_mm_track">' + pinsHtml + '</div>' +
    '</div>';
  }
  function _editCounts() {
    var edits = (_egActive.plan && _egActive.plan.edits) || [];
    var c = { total: edits.length, accepted: 0, rejected: 0, pending: 0 };
    edits.forEach(function (e) {
      var s = _egActive.acceptance[e.id] || "pending";
      if (s === "accepted") c.accepted++;
      else if (s === "rejected") c.rejected++;
      else c.pending++;
    });
    return c;
  }
  function _editCardHtml(e) {
    var status = _egActive.acceptance[e.id] || "pending";
    var statusCls = "_eg_card_" + status;
    var reviewCls = e.requiresHumanReview ? " _eg_card_review" : "";
    var dots = _confidenceDots(e.confidence);
    var typeBadge = '<span class="_eg_type_badge _eg_type_' + (e.type || "replace") + '">' + _esc((e.type || "replace").toUpperCase()) + '</span>';
    // Inline redline (real Word-style) — uses the source paragraph
    // text + applies the change in-place with strikethrough/insert
    // markup, so the user sees the EDIT in context. Falls back to
    // the simple before/after blocks when paragraph text isn't
    // available (e.g., simple-fallback index without bookmarks).
    var diffHtml = _renderInlineDiff(e) || _renderDiff(e);
    var sectionLine = e.section
      ? '<div class="_eg_card_loc_section">📍 ' + _esc(e.section) + '</div>'
      : '<div class="_eg_card_loc_section _eg_card_loc_unknown">📍 Section: not identified</div>';
    var paraLine = "";
    if (e.paragraphIndex && e.paragraphTotal) {
      paraLine = '<div class="_eg_card_loc_para">Paragraph ' + e.paragraphIndex + ' of ' + e.paragraphTotal + '</div>';
    } else if (e.paragraphId) {
      paraLine = '<div class="_eg_card_loc_para">Paragraph ' + _esc(e.paragraphId) + '</div>';
    }
    // Counter-arg / rebuttal block — only renders when populated by
    // the critique pass. Reads as "negotiation prep" — what they'll
    // say, what you say back.
    var negPrep = "";
    if (e.counterargument || e.rebuttal) {
      negPrep =
        '<details class="_eg_card_negprep">' +
          '<summary>⚖️ Negotiation prep</summary>' +
          (e.counterargument ? '<div class="_eg_negprep_row"><span class="_eg_negprep_label">They\'ll say:</span> ' + _esc(e.counterargument) + '</div>' : '') +
          (e.rebuttal ? '<div class="_eg_negprep_row _eg_negprep_rebuttal"><span class="_eg_negprep_label">You can respond:</span> ' + _esc(e.rebuttal) + '</div>' : '') +
        '</details>';
    }
    // If this edit addresses a parsed comment (email agent), show a
    // pill linking back to the comment's author + ask for traceability.
    var commentLink = "";
    if (e.addressesComment && _egActive.parsedComments) {
      var c = _egActive.parsedComments.find(function (x) { return x.id === e.addressesComment; });
      if (c) {
        commentLink = '<div class="_eg_card_comment_link" title="' + _esc(c.originalText || c.ask) + '">' +
          '📧 Addresses ' + _esc(c.id) + (c.author ? ' (' + _esc(c.author) + ')' : '') + ': "' + _esc(_truncate(c.ask, 80)) + '"' +
        '</div>';
      }
    }
    return '<div class="_eg_card ' + statusCls + reviewCls + '" data-eg-edit-id="' + _esc(e.id) + '" id="_eg_card_' + _esc(e.id) + '">' +
      '<div class="_eg_card_loc">' +
        sectionLine +
        paraLine +
      '</div>' +
      commentLink +
      '<div class="_eg_card_top">' +
        '<div class="_eg_card_meta">' +
          typeBadge +
          '<span class="_eg_card_category">' + _esc(e.category || "other") + '</span>' +
          '<span class="_eg_card_dots" title="Confidence: ' + (e.confidence || 3) + '/5">' + dots + '</span>' +
        '</div>' +
        (e.requiresHumanReview ? '<span class="_eg_card_review_pill">⚠ needs review</span>' : '') +
      '</div>' +
      '<div class="_eg_card_diff">' + diffHtml + '</div>' +
      '<div class="_eg_card_rationale">' + _esc(e.rationale || "") + '</div>' +
      negPrep +
      '<div class="_eg_card_actions">' +
        '<button type="button" class="_eg_card_btn _eg_card_locate" data-eg-action="locate" data-eg-edit-id="' + _esc(e.id) + '" title="Jump to this anchor in the document">📍 Locate</button>' +
        '<button type="button" class="_eg_card_btn _eg_card_refine" data-eg-action="refine" data-eg-edit-id="' + _esc(e.id) + '" data-eg-refine="aggressive" title="Re-plan this edit, more aggressive">🔥</button>' +
        '<button type="button" class="_eg_card_btn _eg_card_refine" data-eg-action="refine" data-eg-edit-id="' + _esc(e.id) + '" data-eg-refine="soften" title="Re-plan this edit, more conservative">❄️</button>' +
        '<button type="button" class="_eg_card_btn _eg_card_refine" data-eg-action="refine" data-eg-edit-id="' + _esc(e.id) + '" data-eg-refine="alternative" title="Re-plan this edit with a different approach">🔄</button>' +
        '<button type="button" class="_eg_card_btn _eg_card_accept" data-eg-action="accept" data-eg-edit-id="' + _esc(e.id) + '"' + (status === "accepted" ? ' disabled' : '') + '>✓ Accept</button>' +
        '<button type="button" class="_eg_card_btn _eg_card_reject" data-eg-action="reject" data-eg-edit-id="' + _esc(e.id) + '"' + (status === "rejected" ? ' disabled' : '') + '>✗ Reject</button>' +
        (status !== "pending" ? '<button type="button" class="_eg_card_btn _eg_card_undo" data-eg-action="undo" data-eg-edit-id="' + _esc(e.id) + '">↺ Undo</button>' : '') +
      '</div>' +
    '</div>';
  }
  // ─── Inline redline rendering ─────────────────────────────────────
  // Renders the edit in PARAGRAPH CONTEXT — finds the anchorText
  // within the paragraph, splices in the strikethrough+insert markup,
  // returns a snippet of ~80 chars of context on each side. Reads
  // like opening Word's review pane. Returns "" if it can't render
  // (caller falls back to simple before/after).
  function _renderInlineDiff(e) {
    var paraText = e.paragraphText;
    if (!paraText || typeof paraText !== "string") return "";
    var anchor = String(e.anchorText || "");
    if (!anchor) return "";
    // Case-insensitive locate inside the paragraph text.
    var idx = paraText.toLowerCase().indexOf(anchor.toLowerCase());
    if (idx === -1) return "";
    var actualAnchor = paraText.slice(idx, idx + anchor.length);
    var before = paraText.slice(0, idx);
    var after = paraText.slice(idx + anchor.length);
    // Trim context around the change to ~80 chars each side. Add
    // ellipsis when truncated. Trim on word boundaries.
    var ctxLen = 80;
    var beforeTrim = before;
    if (before.length > ctxLen) {
      var b = before.slice(before.length - ctxLen);
      var firstSpace = b.indexOf(" ");
      if (firstSpace > 0 && firstSpace < 20) b = b.slice(firstSpace + 1);
      beforeTrim = "…" + b;
    }
    var afterTrim = after;
    if (after.length > ctxLen) {
      var a = after.slice(0, ctxLen);
      var lastSpace = a.lastIndexOf(" ");
      if (lastSpace > a.length - 20 && lastSpace > 0) a = a.slice(0, lastSpace);
      afterTrim = a + "…";
    }
    var t = e.type || "replace";
    var changeMarkup = "";
    if (t === "delete") {
      changeMarkup = '<del class="_eg_inline_del">' + _esc(actualAnchor) + '</del>';
    } else if (t === "insert") {
      // For inserts, anchor stays + new content goes before/after.
      var ins = '<ins class="_eg_inline_ins">' + _esc(e.replacementText || "") + '</ins>';
      var before_pos = e.insertPosition === "before";
      changeMarkup = before_pos
        ? ins + ' ' + _esc(actualAnchor)
        : _esc(actualAnchor) + ' ' + ins;
    } else {
      // replace
      changeMarkup =
        '<del class="_eg_inline_del">' + _esc(actualAnchor) + '</del>' +
        '<ins class="_eg_inline_ins">' + _esc(e.replacementText || "") + '</ins>';
    }
    return '<div class="_eg_inline_diff">' +
      _esc(beforeTrim) + changeMarkup + _esc(afterTrim) +
    '</div>';
  }
  function _confidenceDots(n) {
    n = Math.max(1, Math.min(5, n || 3));
    var s = "";
    for (var i = 1; i <= 5; i++) s += (i <= n ? '●' : '○');
    return s;
  }
  function _renderDiff(e) {
    var t = e.type || "replace";
    if (t === "delete") {
      return '<div class="_eg_diff_orig"><del>' + _esc(e.anchorText || "") + '</del></div>';
    }
    if (t === "insert") {
      return '<div class="_eg_diff_orig _eg_diff_insert_anchor">After: <em>' + _esc(_truncate(e.anchorText, 80)) + '</em></div>' +
        '<div class="_eg_diff_new"><ins>' + _esc(e.replacementText || "") + '</ins></div>';
    }
    // replace
    return '<div class="_eg_diff_orig"><del>' + _esc(e.anchorText || "") + '</del></div>' +
      '<div class="_eg_diff_new"><ins>' + _esc(e.replacementText || "") + '</ins></div>';
  }
  function _truncate(s, n) {
    s = String(s || "");
    return s.length <= n ? s : s.slice(0, n) + "…";
  }
  function _wireReviewControls(body) {
    body.querySelectorAll("[data-eg-action]").forEach(function (btn) {
      btn.onclick = function () {
        var action = btn.getAttribute("data-eg-action");
        var id = btn.getAttribute("data-eg-edit-id");
