          var rEdit = (_egActive.plan.edits || []).find(function (e) { return e.id === id; });
          if (rEdit) _refineEdit(rEdit, refineMode, btn);
          return;
        }
        if (action === "accept") _egActive.acceptance[id] = "accepted";
        else if (action === "reject") _egActive.acceptance[id] = "rejected";
        else if (action === "undo") _egActive.acceptance[id] = "pending";
