  }

  // ─── Plan pipeline (multi-stage) ──────────────────────────────────
  // Five stages, each a separate AI call. Streams updates to the UI
  // so the user can watch the agent think instead of staring at a
  // single 30-second spinner.
  //
  //   1. capturing      — read/warm the QA index + load playbooks
  //   2. strategy       — Pass A: AI identifies "buckets" (areas to revise)
  //   3. buckets        — Pass B (parallel): one AI call per bucket
  //                       generates focused edits for that area
  //   4. critique       — Pass C: AI reviews its own work, drops weak
  //                       edits, refines rationales, adds counter-arg
  //                       + rebuttal for each surviving edit
  //   5. enrichment     — Passes D + E in parallel:
  //                         D: scans for things the user DIDN'T ask
  //                            about but should know (unrequested findings)
  //                         E: proposes negotiation presentation order
  //   6. review         — final state, all panels populated
  //
  // Cancellation: each stage gets its own cancel token. Closing the
  // overlay aborts whichever stage is in flight.
  function _runPlan() {
    if (!_egActive) return Promise.resolve();
    _egActive.status = "capturing";
    _egActive.strategy = null;
    _egActive.bucketProgress = {};
    _egActive.plan = { summary: "", edits: [], unrequested: [], negotiationStrategy: null };
    _egActive.acceptance = {};
    _renderOverlayBody();
    return _ensureQaIndex().then(function (idx) {
      if (!_egActive) return;
      _egActive.qaIndex = idx.qaIndex || [];
      _egActive.docHash = idx.docHash || null;
      _egActive.indexSource = idx.source || "unknown";
      if (!_egActive.qaIndex.length) {
        throw new Error(idx.source === "fallback_failed"
          ? "Couldn't read the document — check that it's open and try again."
          : "Document appears empty — add some content and try again.");
      }
      // Load the agent's settings + relevant playbooks in parallel.
      return Promise.all([
        _getAgentSettings(_egActive.agent),
        _loadPlaybookSnippets(),
      ]);
    }).then(function (results) {
      if (!_egActive) return;
      var settings = results[0];
      var playbooks = results[1] || [];
      _egActive.settings = settings;
      _egActive.playbooks = playbooks;
      // ── STAGE 2: Strategy ──
      _egActive.status = "strategy";
      _renderOverlayBody();
      return _runStrategyPass();
    }).then(function (strategy) {
      if (!_egActive) return;
      _egActive.strategy = strategy;
      // ── STAGE 3: Buckets (parallel) ──
      _egActive.status = "buckets";
      _renderOverlayBody();
      return _runBucketPasses(strategy.buckets);
    }).then(function (allEdits) {
      if (!_egActive) return;
      // Stage 3 produced raw edits. Validate to drop malformed.
      _egActive.plan.edits = _validateEdits(allEdits);
      _egActive.plan.summary = _composeSummary(_egActive.strategy, _egActive.plan.edits);
      _renderOverlayBody();
      // ── STAGE 4: Self-critique ──
      _egActive.status = "critique";
      _renderOverlayBody();
      return _runCritiquePass(_egActive.plan.edits);
    }).then(function (refinedEdits) {
      if (!_egActive) return;
      _egActive.plan.edits = _validateEdits(refinedEdits);
      _renderOverlayBody();
      // ── STAGE 5: Enrichment (parallel) ──
      _egActive.status = "enrichment";
      _renderOverlayBody();
      return Promise.all([
        _runProactivePass(),
        _runNegotiationStrategyPass(_egActive.plan.edits),
      ]);
    }).then(function (extras) {
      if (!_egActive) return;
      _egActive.plan.unrequested = (extras[0] && extras[0].unrequested) || [];
      _egActive.plan.negotiationStrategy = extras[1] || null;
      // Initialize acceptance state.
      _egActive.acceptance = {};
      _egActive.plan.edits.forEach(function (e) { _egActive.acceptance[e.id] = "pending"; });
      _egActive.status = "review";
      _egActive.cancelToken = null;
      _renderOverlayBody();
      eli.log.event("tool", "eli_agent_plan_ready", {
        agent: _egActive.agent,
        editCount: _egActive.plan.edits.length,
        unrequestedCount: _egActive.plan.unrequested.length,
        bucketCount: _egActive.strategy && _egActive.strategy.buckets ? _egActive.strategy.buckets.length : 0,
        indexSource: _egActive.indexSource,
        playbookCount: _egActive.playbooks.length,
      });
    }).catch(function (err) {
      if (!_egActive) return;
      // Cancel-induced errors shouldn't show as failures.
      if (err && (err.name === "AbortError" || /cancel/i.test(String(err.message)))) {
        return; // user aborted, status was already set
      }
      _egActive.status = "error";
      _egActive.error = (err && err.message) || String(err);
      _egActive.cancelToken = null;
      _renderOverlayBody();
      eli.log.event("tool", "eli_agent_plan_failed", { msg: _egActive.error });
    });
  }
  // ─── Email-to-Redline pipeline (variant of _runPlan) ─────────────
  // After the compose pane finishes:
  //   1. parsing_comments  — Pass 0: parse raw email/blob into structured comments
  //   2. confirm_comments  — UI checkpoint; user confirms / skips
  //   3. capturing         — warm QA index
  //   4. buckets           — per-comment edit generation (one AI call per kept comment)
  //   5. critique          — same as Revise agent
  //   6. enrichment        — proactive + negotiation order
  //   7. review (grouped by comment)
  // Called from the compose pane's "Plan Edits →" button.
  function _runEmailAgentPipeline() {
    if (!_egActive) return Promise.resolve();
    if (!_egActive.commentSource || !_egActive.commentSource.trim()) return Promise.resolve();
    _egActive.status = "parsing_comments";
    _renderOverlayBody();
    var prompt = _buildParseCommentsPrompt(_egActive);
    return _aiJsonCall(prompt, { comments: "object" })
      .then(function (result) {
        if (!_egActive) return;
        var comments = (result && Array.isArray(result.comments)) ? result.comments : [];
        // Normalize each parsed comment.
        var seenIds = {};
        var normalized = [];
        comments.forEach(function (c, idx) {
          if (!c || typeof c !== "object") return;
          var id = String(c.id || ("c" + (idx + 1)));
          if (seenIds[id]) id = id + "_" + idx;
          seenIds[id] = true;
          if (!c.ask || typeof c.ask !== "string" || !c.ask.trim()) return;
          var sev = (c.severity === "high" || c.severity === "must-fix" || c.severity === "med" || c.severity === "low" || c.severity === "nit")
            ? c.severity : "med";
          normalized.push({
            id: id,
            author: typeof c.author === "string" ? c.author : "",
            scope: typeof c.scope === "string" ? c.scope : "",
            ask: c.ask.trim(),
            severity: sev,
            originalText: typeof c.originalText === "string" ? c.originalText : "",
            skipped: false,
          });
        });
