    });
  }

  // ─── Response email generation (final email-agent step) ─────────
  // Takes the parsed comments + applied edits + failures and produces
  // an email-style summary for the user to paste back to whoever sent
  // the comments. Stays in the agent overlay (status: response_email).
  function _runResponseEmailGeneration() {
    if (!_egActive) return;
    _egActive.status = "drafting_email";
    _renderOverlayBody();
    var prompt = _buildResponseEmailPrompt(_egActive);
    _egActive.cancelToken = (eli.cancel && typeof eli.cancel.token === "function")
      ? eli.cancel.token() : null;
    var opts = { sanitize: false };
    if (_egActive.cancelToken && _egActive.cancelToken.signal) opts.signal = _egActive.cancelToken.signal;
    return eli.ai.complete(prompt, opts).then(function (text) {
      if (!_egActive) return;
      _egActive.responseEmail = String(text || "").trim();
      _egActive.status = "response_email";
      _egActive.cancelToken = null;
      _renderOverlayBody();
      eli.log.event("tool", "eli_agent_response_email_drafted", { length: _egActive.responseEmail.length });
    }).catch(function (err) {
      if (!_egActive) return;
