  }
  function _buildResponseEmailPrompt(active) {
    var comments = active.parsedComments || [];
    var applied = (active.applyResult && active.applyResult.appliedEdits) || [];
    var failures = (active.applyResult && active.applyResult.failures) || [];
    var rejected = (active.plan && active.plan.edits || []).filter(function (e) {
      return active.acceptance[e.id] === "rejected";
    });
    // Build per-comment outcome summary.
    var commentOutcomes = comments.map(function (c) {
      if (c.skipped) return { id: c.id, status: "skipped", author: c.author, ask: c.ask, edits: [] };
      var matchingApplied = applied.filter(function (e) { return e.addressesComment === c.id; });
      var matchingRejected = rejected.filter(function (e) { return e.addressesComment === c.id; });
      var matchingFailed = failures.filter(function (f) { return f.edit && f.edit.addressesComment === c.id; });
      var status =
        matchingApplied.length > 0 ? "addressed" :
        matchingFailed.length > 0 ? "blocked" :
        matchingRejected.length > 0 ? "declined" :
        "punted";
      return {
        id: c.id, status: status, author: c.author, scope: c.scope, ask: c.ask,
        editsApplied: matchingApplied.length, editsFailed: matchingFailed.length, editsRejected: matchingRejected.length,
      };
    });
    var primaryAuthor = comments.length && comments[0].author ? comments[0].author : "there";
    return [
      "You are drafting a brief, professional response email to a colleague who sent comments on a contract.",
      "The email summarizes which of their comments were addressed, which were punted, which were blocked.",
      "Tone: collegial, concise, no legalese. 4-8 lines max body. Use bullet points for the per-comment recap.",
      "",
      "OUTPUT: just the email body text — no subject line, no greeting if it would feel forced. Start with \"Hi " + primaryAuthor + ",\" or similar if appropriate.",
      "",
      "═══ ORIGINAL COMMENTS RECEIVED ═══",
      JSON.stringify(comments.map(function (c) {
        return { id: c.id, author: c.author, scope: c.scope, ask: c.ask };
      }), null, 1),
      "",
      "═══ OUTCOMES ═══",
      JSON.stringify(commentOutcomes, null, 1),
      "",
      "FORMAT GUIDE:",
      "- For 'addressed': \"✓ §X — [brief description of edit landed]\"",
      "- For 'punted': \"⚠ Topic — [why I'm flagging back instead of editing]\"",
      "- For 'blocked': \"❌ §X — [what I couldn't find / why]\"",
      "- For 'declined': \"⚪ §X — chose not to make this change [if you want to share reasoning]\"",
      "",
      "End with a 1-line close like \"Redlines attached. Let me know.\"",
    ].join("\n");
  }

  // ─── Draft Agreement: pipeline ───────────────────────────────────
  function _runDraftPipeline() {
    if (!_egActive) return;
    _egActive.status = "outline";
    _renderOverlayBody();
    return Promise.all([
      _getAgentSettings(_egActive.agent),
      _loadPlaybookSnippets(),
    ]).then(function (results) {
      _egActive.settings = results[0];
      _egActive.playbooks = results[1] || [];
      // Build outline.
