      return _aiJsonCall(prompt, { sections: "object" });
    }).then(function (result) {
      if (!_egActive) return;
      var sections = (result && Array.isArray(result.sections)) ? result.sections : [];
      // Normalize: assign id + num, default status queued.
      _egActive.outline = sections.map(function (s, i) {
        return {
          id: "s" + (i + 1),
          num: typeof s.num === "string" || typeof s.num === "number" ? String(s.num) : String(i + 1),
          name: typeof s.name === "string" ? s.name : "Section " + (i + 1),
          focus: typeof s.focus === "string" ? s.focus : "",
          status: "queued",
          content: "",
        };
        // Initialize draft acceptance to "accept" for all.
