    _renderOverlayBody();
    // Parallel: one AI call per section. Each one updates s.content
    // + s.status as it completes. Stream updates so user sees progress.
    var promises = _egActive.outline.map(function (s) {
      var prompt = _buildSectionDraftPrompt(_egActive, s);
      return eli.ai.complete(prompt, { sanitize: false })
        .then(function (text) {
          s.content = String(text || "").trim();
          s.status = "done";
