      _renderOverlayBody();
    });
  }
  function _regenerateDraftSection(sectionId, btnEl) {
    var s = (_egActive.outline || []).find(function (x) { return x.id === sectionId; });
    if (!s) return;
    var orig = btnEl ? btnEl.innerHTML : "";
    if (btnEl) { btnEl.innerHTML = "⚙"; btnEl.disabled = true; }
    s.status = "drafting";
    var prompt = _buildSectionDraftPrompt(_egActive, s) + "\n\nNOTE: Generate an ALTERNATIVE version — different wording, different structure than before.";
    return eli.ai.complete(prompt, { sanitize: false })
      .then(function (text) {
        s.content = String(text || "").trim();
        s.status = "done";
        _renderOverlayBody();
      }).catch(function (err) {
        s.status = "failed";
        if (btnEl) {
          btnEl.innerHTML = "⚠";
          setTimeout(function () { if (btnEl) { btnEl.innerHTML = orig; btnEl.disabled = false; } }, 1400);
        }
        _toast("Regenerate failed: " + (err && err.message), "err");
      });
  }
  function _insertAcceptedDraftSections() {
    var accepted = (_egActive.outline || []).filter(function (s) {
      return (_egActive.draftAcceptance[s.id] || "accept") === "accept" && s.content;
    });
    if (!accepted.length) return;
    _egActive.status = "inserting_draft";
    _renderOverlayBody();
    return eli.host.runRaw("eli_agent:insert_draft", function (context) {
      var body = context.document.body;
      // Insert each accepted section at end of doc: heading + body text.
      accepted.forEach(function (s) {
        // Section heading paragraph.
        body.insertParagraph("§" + s.num + " " + s.name, "End");
        // Body paragraphs — split content on double-newline.
        var paras = String(s.content || "").split(/\n\n+/);
        paras.forEach(function (p) {
          var t = p.replace(/\n/g, " ").trim();
          if (t) body.insertParagraph(t, "End");
        });
        body.insertParagraph("", "End");  // blank separator
      });
      return context.sync().then(function () {
        return { inserted: accepted.length, failures: [] };
      });
    }).then(function (result) {
      if (!_egActive) return;
      _egActive.draftInsertResult = result;
      _egActive.status = "draft_inserted";
      _renderOverlayBody();
      eli.log.event("tool", "eli_agent_draft_inserted", { sections: result.inserted });
    }).catch(function (err) {
      if (!_egActive) return;
      _egActive.draftInsertResult = { inserted: 0, failures: [{ reason: (err && err.message) || String(err) }] };
      _egActive.status = "draft_inserted";
      _renderOverlayBody();
    });
  }

  // ─── Draft Agreement: prompts ────────────────────────────────────
  function _buildInterviewTurnPrompt(active, lastAnswer) {
    var iv = active.interview;
    var historyJson = JSON.stringify({
      seed: iv.seed,
      turns: iv.turns,
      agreementType: iv.agreementType,
    }, null, 1);
    var phase = iv.turns.length < 2 ? "BIG_PICTURE" : iv.turns.length < 5 ? "DETAILS" : "WRAPPING_UP";
    return [
      "You are an associate attorney intaking a new contract drafting request via conversational Q&A.",
      "Each turn, you ask ONE focused question — never more than one at a time.",
      "Return JSON only.",
      "",
      "PHASE: " + phase,
      phase === "BIG_PICTURE" ? "Establish: what kind of agreement, who are the parties, key commercial deal points." :
        phase === "DETAILS" ? "Drill into specifics: terms, IP, indemnity scope, termination, governing law." :
        "Final clarifying questions. After 1-2 more turns, set intakeComplete: true.",
      "",
      "OUTPUT SHAPE:",
      "{",
      "  \"intakeComplete\": false,",
      "  \"agreementType\": \"NDA\" | \"MSA\" | \"Distribution\" | \"Consulting\" | \"Other (describe)\" | null,",
      "  \"questions\": [",
      "    { \"question\": \"Who are the parties?\", \"type\": \"text\" },",
      "    { \"question\": \"Mutual or one-way confidentiality?\", \"type\": \"choice\", \"options\": [\"Mutual\", \"One-way\"] }",
      "  ]",
      "}",
      "",
      "RULES:",
      "1. EXACTLY ONE question per turn unless they're tightly related multi-part (max 2).",
      "2. type: 'text' for open-ended, 'choice' for picks (always include `options` array of 2-5 strings).",
      "3. Set intakeComplete: true when you have enough to start drafting (typically after 4-6 substantive turns).",
      "4. If the user's last answer suggests they want to start drafting NOW, set intakeComplete: true immediately.",
      "5. Don't repeat questions you've already asked.",
      "6. Update agreementType as soon as it's clear.",
      "",
      "═══ INTERVIEW HISTORY ═══",
      historyJson,
      "",
      "═══ LAST USER ANSWER ═══",
      lastAnswer === null ? "(user clicked 'Add more context' — keep asking)" : String(lastAnswer || "(initial turn — kick off)"),
    ].join("\n");
  }
  function _buildOutlinePrompt(active) {
    var iv = active.interview || {};
    var pbSnippets = (active.playbooks || []).slice(0, 12).map(function (p) {
      return "  • " + p.clauseName;
    }).join("\n");
    return [
      "You are an associate attorney designing an outline for a contract draft.",
      "Based on the intake interview below, produce a numbered section outline.",
      "Return JSON only.",
      "",
      "OUTPUT SHAPE:",
      "{",
      "  \"sections\": [",
      "    {\"num\": \"1\", \"name\": \"Definitions\", \"focus\": \"Define all capitalized terms used in this NDA.\"},",
      "    {\"num\": \"2\", \"name\": \"Confidential Information\", \"focus\": \"Scope of what's protected and what's excluded.\"}",
      "  ]",
      "}",
      "",
      "RULES:",
      "1. 6-15 sections typical for a contract. Don't include front-matter (parties block, recitals — those are handled separately).",
      "2. Each section: short name + 1-2 sentence focus describing what content goes in it.",
      "3. Use standard ordering for this agreement type (whatever the type is).",
      "4. Include boilerplate at the end (notices, governing law, entire agreement, etc.) as their own short sections.",
      "",
      "═══ AGREEMENT TYPE ═══",
      iv.agreementType || "(not specified)",
      "",
      "═══ INTAKE INTERVIEW ═══",
      JSON.stringify({ seed: iv.seed, turns: iv.turns }, null, 1),
      pbSnippets ? "\n═══ PLAYBOOK CLAUSES AVAILABLE ═══\n" + pbSnippets +
        "\nFavor outline sections that map to playbook clauses where appropriate." : "",
    ].join("\n");
  }
  function _buildSectionDraftPrompt(active, section) {
    var iv = active.interview || {};
    var pbMatch = (active.playbooks || []).filter(function (p) {
      return p.clauseName.toLowerCase().indexOf(section.name.toLowerCase()) !== -1 ||
        section.name.toLowerCase().indexOf(p.clauseName.toLowerCase()) !== -1;
    }).slice(0, 3);
    var pbBlock = pbMatch.length
      ? "\n═══ PREFERRED LANGUAGE FROM YOUR PLAYBOOKS ═══\n" + pbMatch.map(function (p) {
          return "  • " + p.clauseName + ":\n    " + p.preferredLanguage.replace(/\n/g, " ").slice(0, 800);
        }).join("\n") +
        "\nUSE this language as the starting point. Only modify if the user's intake answers require it."
      : "";
    return [
      "You are drafting a single section of a contract.",
      "Output: the clause text only — no section number, no preamble, no explanation, no markdown fences.",
      "Style: clean legal prose, definitions capitalized, party names consistent. 1-5 paragraphs typical.",
      "",
      "═══ AGREEMENT TYPE ═══",
      iv.agreementType || "(generic)",
      "",
      "═══ THIS SECTION ═══",
      "§" + section.num + " " + section.name,
      "Focus: " + section.focus,
      "",
      "═══ DEAL-SPECIFIC CONTEXT (from intake interview) ═══",
      JSON.stringify({ seed: iv.seed, turns: iv.turns }, null, 1),
      pbBlock,
    ].join("\n");
  }

  // Parse-comments prompt. Pass 0 of the email agent.
  function _buildParseCommentsPrompt(active) {
    return [
      "You are receiving a raw blob of feedback on a legal document. Could be an email, a comment thread, Word comments, or all of the above.",
      "Parse it into structured comments. Each individual ask becomes one comment object.",
      "Return JSON only.",
      "",
      "OUTPUT SHAPE (example):",
      "{",
      "  \"comments\": [",
      "    {",
      "      \"id\": \"c1\",",
      "      \"author\": \"Sarah\",",
      "      \"scope\": \"§4.2 Payment Terms\",",
      "      \"ask\": \"Extend payment from 30 to 60 days\",",
      "      \"severity\": \"must-fix\",",
      "      \"originalText\": \"Sarah: 'Payment in 30 days is too aggressive — let's push to 60.'\"",
      "    }",
      "  ]",
      "}",
      "",
      "RULES:",
      "1. id: c1, c2, c3… (unique, sequential).",
      "2. author: best guess from the text. Leave empty if unclear.",
      "3. scope: what part of the doc this is about (section, clause, topic). Leave empty if doc-wide.",
      "4. ask: ONE specific thing the commenter wants. If they raise multiple issues in one paragraph, split into multiple comments.",
      "5. severity: 'must-fix' (substantive), 'med' (worth addressing), 'low' (nit), 'high' (critical).",
      "6. originalText: a verbatim quote (≤200 chars) of the relevant excerpt for trace-back.",
      "7. Don't include greetings, sign-offs, or chit-chat as comments — only substantive asks.",
      "",
      "═══ RAW FEEDBACK ═══",
      active.commentSource,
    ].join("\n");
  }

  // Per-stage AI call helper — wraps eli.ai.completeJSON with a
  // fresh cancel token that the Cancel button can abort.
  function _aiJsonCall(prompt, schema) {
    _egActive.cancelToken = (eli.cancel && typeof eli.cancel.token === "function")
      ? eli.cancel.token() : null;
    var opts = { sanitize: false };
    if (_egActive.cancelToken && _egActive.cancelToken.signal) {
      opts.signal = _egActive.cancelToken.signal;
    }
    return eli.ai.completeJSON(prompt, schema, opts);
  }
  function _runStrategyPass() {
    var prompt = _buildStrategyPrompt(_egActive);
    return _aiJsonCall(prompt, { summary: "string", buckets: "object" })
      .then(function (s) {
        if (!s || !Array.isArray(s.buckets) || !s.buckets.length) {
          // Fallback: synthesize a single bucket spanning the whole doc.
          return { summary: "", buckets: [{ name: "Document review", focus: _egActive.instruction, scope: "Entire document" }] };
        }
        return s;
      });
  }
  function _runBucketPasses(buckets) {
    // Initialize per-bucket progress so the streaming UI can show it.
    buckets.forEach(function (b) {
      _egActive.bucketProgress[b.name] = { status: "running", editCount: 0 };
    });
    _renderOverlayBody();
    var allEdits = [];
    var nextId = 1;
    var promises = buckets.map(function (b) {
      var prompt = _buildBucketPrompt(_egActive, b);
      return _aiJsonCall(prompt, { edits: "object" })
        .then(function (result) {
          var edits = (result && Array.isArray(result.edits)) ? result.edits : [];
          edits.forEach(function (e) {
            // Re-id to globally-unique values so dedup is trivial.
            e.id = "e" + (nextId++);
            e.bucket = b.name;
            allEdits.push(e);
          });
          _egActive.bucketProgress[b.name] = { status: "done", editCount: edits.length };
          // Live update — append edits to plan as buckets complete.
          _egActive.plan.edits = _validateEdits(allEdits);
          _renderOverlayBody();
          return edits;
        }).catch(function (err) {
          _egActive.bucketProgress[b.name] = { status: "failed", editCount: 0, error: (err && err.message) || String(err) };
          _renderOverlayBody();
          return [];
        });
    });
    return Promise.all(promises).then(function () { return allEdits; });
  }
  function _runCritiquePass(edits) {
    if (!edits || !edits.length) return Promise.resolve([]);
    var prompt = _buildCritiquePrompt(_egActive, edits);
    return _aiJsonCall(prompt, { edits: "object" })
      .then(function (result) {
        var refined = (result && Array.isArray(result.edits)) ? result.edits : edits;
        // Defense: if critique returned nothing, keep the originals.
        if (!refined.length) return edits;
        return refined;
      })
      .catch(function () { return edits; });  // fail-open: don't lose work
  }
  function _runProactivePass() {
    var prompt = _buildProactivePrompt(_egActive);
    return _aiJsonCall(prompt, { unrequested: "object" })
      .then(function (r) { return r || { unrequested: [] }; })
      .catch(function () { return { unrequested: [] }; });
  }
  function _runNegotiationStrategyPass(edits) {
    if (!edits || edits.length < 2) return Promise.resolve(null);
    var prompt = _buildNegotiationStrategyPrompt(_egActive, edits);
    return _aiJsonCall(prompt, { rationale: "string", rounds: "object" })
      .then(function (r) { return r || null; })
      .catch(function () { return null; });
  }
  function _composeSummary(strategy, edits) {
    var bucketsLine = (strategy && strategy.summary) || "";
    if (bucketsLine) return bucketsLine;
    return "Proposed " + edits.length + " edit" + (edits.length === 1 ? "" : "s") +
      " across " + (strategy && strategy.buckets ? strategy.buckets.length : 1) +
      " area" + (strategy && strategy.buckets && strategy.buckets.length === 1 ? "" : "s") + ".";
  }
  function _validateEdits(edits) {
    return _validatePlan({ summary: "", edits: edits }).edits;
  }
  // ─── Playbook integration ─────────────────────────────────────────
  // Pull saved playbooks (per-agreement-type clause guidance + sample
  // language) so per-bucket prompts can suggest using YOUR proven
  // language instead of AI-generated prose. Best-effort: empty list
  // is a graceful degrade. Currently grabs all stored playbooks; V2
  // could filter by detected agreement type.
  function _loadPlaybookSnippets() {
    if (!eli.storage || typeof eli.storage.getAll !== "function") return Promise.resolve([]);
    return eli.storage.getAll("playbooks").then(function (rows) {
      if (!Array.isArray(rows)) return [];
      // Each row shape varies — extract clause-level entries when present.
      var snippets = [];
      rows.forEach(function (row) {
        if (!row) return;
        var content = null;
        try { content = typeof row.content === "string" ? JSON.parse(row.content) : row.content; }
        catch (_e) { return; }
        var entries = (content && (content.clauses || content.entries || content.items)) || null;
        if (!Array.isArray(entries)) return;
        entries.forEach(function (entry) {
          if (!entry) return;
          var name = entry.name || entry.title || entry.clause || null;
          var preferred = entry.preferred || entry.sampleLanguage || entry.language || null;
          if (name && preferred) {
            snippets.push({
              source: row.name || row.id || "playbook",
              clauseName: String(name),
              preferredLanguage: String(preferred).slice(0, 600),
            });
          }
        });
      });
      return snippets.slice(0, 30); // cap for token budget
    }).catch(function () { return []; });
  }
  function _ensureQaIndex() {
    // Three-tier strategy.
    //   Tier A: ask_eli's cached QA index — instant when already warm.
    //   Tier B: ask_eli's `warm_qa_index` dispatch — actively triggers
    //   a fresh build (10-20s on first warm, then cache hit). Has
    //   paragraph bookmarks + section labels (best for apply).
    //   Tier C: build a minimal index ourselves via direct Word.js
    //   read. Last-resort fallback when ask_eli isn't loaded.
    // Always prefer A → B → C.
    try {
      var cached = eli.dispatch("ask_eli", "get_qa_index");
      if (cached && Array.isArray(cached.qaIndex) && cached.qaIndex.length) {
        return Promise.resolve({
          qaIndex: cached.qaIndex,
          docHash: cached.docHash,
          source: "ask_eli_cached",
        });
      }
    } catch (_) {}
    // Try the warmed-on-demand path.
    try {
      var warmPromise = eli.dispatch("ask_eli", "warm_qa_index");
      if (warmPromise && typeof warmPromise.then === "function") {
        return warmPromise.then(function (result) {
          if (result && Array.isArray(result.qaIndex) && result.qaIndex.length) {
            return {
              qaIndex: result.qaIndex,
              docHash: result.docHash,
              source: "ask_eli_warmed",
            };
          }
          return _buildSimpleIndex();
        }).catch(function () { return _buildSimpleIndex(); });
      }
    } catch (_) {}
    return _buildSimpleIndex();
  }
  // Fallback index — read body paragraphs directly. Skips empty paras
  // and very-short noise (page numbers, single chars) so the prompt
  // stays focused on substantive content. Synthetic ids "_eg_p_<n>"
  // — apply path falls back to body-wide search since these aren't
  // real Word bookmarks.
  function _buildSimpleIndex() {
    if (!eli.host || typeof eli.host.runRaw !== "function") {
      return Promise.resolve({ qaIndex: [], docHash: null, source: "fallback_unavailable" });
    }
    return eli.host.runRaw("eli_agent:fallback_index", function (context) {
      var paragraphs = context.document.body.paragraphs;
      paragraphs.load("text");
      return context.sync().then(function () {
        var items = paragraphs.items || [];
        var index = [];
        for (var i = 0; i < items.length; i++) {
          var t = String(items[i].text || "").trim();
          if (t.length < 3) continue;  // skip page-number / noise paragraphs
          index.push({
            id: "_eg_p_" + i,
            text: t.length > 1500 ? t.slice(0, 1500) + "…" : t,
            section: null,
          });
        }
        return { qaIndex: index, docHash: null, source: "fallback" };
      });
    }).catch(function (err) {
      eli.log.event("tool", "eli_agent_fallback_index_failed", { msg: err && err.message });
      return { qaIndex: [], docHash: null, source: "fallback_failed" };
    });
  }

  // ─── Stage prompts ────────────────────────────────────────────────
  // 1. Strategy — short scan that returns "buckets" (focus areas).
  // 2. Bucket  — focused per-area edit generation.
  // 3. Critique — review + drop weak + add counter-args/rebuttals.
  // 4. Proactive — find issues the user didn't ask about.
  // 5. Negotiation order — propose presentation rounds.
  function _toneGuide(tone) {
    if (tone === "aggressive")   return "Take a strong position in favor of the requestor. Push for materially better terms across all in-scope categories. Err on MORE edits, not fewer.";
    if (tone === "conservative") return "Make modest, market-standard adjustments only. Avoid edits likely to be rejected as unreasonable.";
    return "Balanced — propose edits that improve the requestor's position with terms a sophisticated counterparty would likely accept. Err on MORE potential improvements, not fewer.";
  }
  function _docPayload(active) {
    return JSON.stringify(active.qaIndex, null, 1);
  }

  function _buildStrategyPrompt(active) {
    var tone = (active.settings && active.settings.tone) || "balanced";
    return [
      "You are a senior associate planning a contract revision pass.",
      "Read the document below + the client's instruction. Identify the AREAS where edits are warranted.",
      "Return JSON only. Do NOT propose specific edits — just identify the buckets to focus on.",
      "",
      "OUTPUT SHAPE (example):",
      "{",
      "  \"summary\": \"Tilted payment, indemnity, MFN, and termination in Colgate's favor.\",",
      "  \"buckets\": [",
      "    {\"name\": \"Payment Terms\",  \"focus\": \"extend payment timing, reduce late-fee interest, add grace period\", \"scope\": \"Article IV\"},",
      "    {\"name\": \"Indemnity\",       \"focus\": \"cap exposure, narrow trigger, add carve-outs\", \"scope\": \"§7-8\"},",
      "    {\"name\": \"MFN Protection\",  \"focus\": \"add missing MFN clause\", \"scope\": \"§11\"},",
      "    {\"name\": \"Termination\",     \"focus\": \"extend notice, add wind-down\", \"scope\": \"§10\"}",
      "  ]",
      "}",
      "",
      "RULES:",
      "1. Identify 3-8 buckets — enough to be thorough, not so many they overlap.",
      "2. Each bucket has a unique short `name` (used downstream as a key).",
      "3. `focus` is 1-2 sentences on what kinds of edits to look for in this bucket.",
      "4. `scope` references doc sections by number/title where present.",
      "5. `summary` is 1-2 sentences describing the overall revision strategy.",
      "",
      "TONE: " + _toneGuide(tone),
      "",
      "═══ INSTRUCTION ═══",
      active.instruction,
      "",
      "═══ DOCUMENT (paragraph-indexed JSON — id, text, section) ═══",
      _docPayload(active),
    ].join("\n");
  }

  function _buildBucketPrompt(active, bucket) {
    var tone = (active.settings && active.settings.tone) || "balanced";
    var pbSnippets = (active.playbooks || []).slice(0, 8).map(function (p) {
      return "  • " + p.clauseName + " (from " + p.source + "):\n      " +
        p.preferredLanguage.replace(/\n/g, " ").slice(0, 400);
    }).join("\n");
    var pbBlock = pbSnippets
      ? "\n═══ PREFERRED LANGUAGE FROM YOUR PLAYBOOKS ═══\n" + pbSnippets +
        "\nWhen proposing edits in matching categories, USE this language verbatim where it fits.\n"
      : "";
    // When the bucket is from the email agent, it carries a commentRef.
    // Inject the original commenter's verbatim language so the AI can
    // cite it in rationales + addressesComment field on each edit.
    var commentBlock = "";
    if (bucket.commentRef) {
      var c = bucket.commentRef;
      commentBlock =
        "\n═══ ORIGINAL COMMENT (from " + (c.author || "the reviewer") + ") ═══\n" +
        "Quote: \"" + (c.originalText || c.ask) + "\"\n" +
        "Severity: " + (c.severity || "med") + "\n" +
        "Comment ID: " + c.id + "\n" +
        "RULES FOR THIS BUCKET:\n" +
        " • Each edit MUST include `addressesComment: \"" + c.id + "\"` in its JSON.\n" +
        " • Reference the commenter's language in the rationale (e.g., \"Direct response to " + (c.author || "the reviewer") + "'s ask...\").\n" +
        " • If the comment is NOT actionable (vague, judgment-call, or refers to something not in the doc), return an empty edits array — the orchestrator will mark this comment as 'punted' or 'blocked'.\n";
    }
    return [
      "You are a senior associate generating specific contract edits for a SINGLE focus area.",
      "Generate every relevant edit for this bucket. Be thorough — 2-6 edits per bucket is typical.",
      "Return JSON only.",
      "",
      "OUTPUT SHAPE (example):",
      "{",
      "  \"edits\": [",
      "    {",
      "      \"type\": \"replace\",",
      "      \"paragraphId\": \"ELI_QA_14\",",
      "      \"section\": \"§4.2 Payment Terms\",",
      "      \"anchorText\": \"thirty (30) days\",",
      "      \"replacementText\": \"sixty (60) days\",",
      "      \"rationale\": \"Extends working-capital cycle.\",",
      "      \"category\": \"payment-terms\",",
      "      \"confidence\": 5,",
      "      \"requiresHumanReview\": false",
      "    }",
      "  ]",
      "}",
      "",
      "RULES:",
      "1. `anchorText` MUST be a verbatim text snippet from the document (5-20 words, unique within the paragraph).",
      "2. `paragraphId` MUST exactly match the `id` of one of the paragraphs below.",
      "3. `section`: COPY VERBATIM from the paragraph's `section` field below. If the paragraph has no section field, omit it. DO NOT invent or guess section numbers — do not infer from text content that mentions \"Section X\" inline. The orchestrator will fill in the correct section from the document's structural map; your `section` field will be overridden if it differs.",
      "4. `type`: 'replace', 'insert' (with insertPosition: 'before'|'after'), or 'delete'.",
      "5. Confidence (1-5): 5 = standard market move, 4 = reasonable, 3 = aggressive, 2-1 = unusual/risky.",
      "6. Set `requiresHumanReview: true` for judgment-heavy edits (asymmetric obligations, removing whole clauses, scope shifts).",
      "7. Categories: payment-terms, indemnity, ip, termination, mfn, audit, warranty, confidentiality, dispute-resolution, boilerplate, other.",
      "8. Don't number `id` — orchestrator will assign globally-unique ids.",
      "",
      "TONE: " + _toneGuide(tone),
      "",
      "═══ FOCUS AREA: " + bucket.name + " ═══",
      "Focus: " + (bucket.focus || ""),
      "Scope: " + (bucket.scope || "any"),
      commentBlock,
      "",
      "═══ CLIENT'S OVERALL INSTRUCTION ═══",
      active.instruction || (bucket.commentRef ? "Address each comment with edits to the document." : ""),
      pbBlock,
      "",
      "═══ DOCUMENT (paragraph-indexed JSON) ═══",
      _docPayload(active),
    ].join("\n");
  }

  function _buildCritiquePrompt(active, edits) {
    return [
      "You are a senior partner reviewing a junior associate's proposed redlines.",
      "Your job: improve the plan. For each edit, you may:",
      "  • DROP it (don't include in output) if weak, redundant, low-value, or it doesn't actually advance the client's instruction",
      "  • REFINE it: tighten the rationale, reword the replacement for cleaner prose, sharpen the anchor",
      "  • ENRICH it with two NEW fields: counterargument + rebuttal (always add these)",
      "Return ALL surviving edits in the same shape, plus the new fields.",
      "",
      "OUTPUT SHAPE:",
      "{",
      "  \"edits\": [",
      "    {",
      "      \"id\": \"e1\",",
      "      \"type\": \"replace\",",
      "      \"paragraphId\": \"ELI_QA_14\",",
      "      \"section\": \"§4.2\",",
      "      \"anchorText\": \"...\",",
      "      \"replacementText\": \"...\",",
      "      \"rationale\": \"refined version\",",
      "      \"category\": \"payment-terms\",",
      "      \"confidence\": 5,",
      "      \"requiresHumanReview\": false,",
      "      \"counterargument\": \"What opposing counsel will likely say\",",
      "      \"rebuttal\": \"How you can respond\"",
      "    }",
      "  ]",
      "}",
      "",
      "RULES:",
      "1. Preserve `id`, `paragraphId`, and `section` VERBATIM from the input — don't renumber, don't relabel sections. DO NOT rewrite section numbers based on clause content (the orchestrator owns section labels via the doc's structural map).",
      "2. counterargument: 1-2 sentences predicting the most likely pushback. Be realistic; don't soft-pedal.",
      "3. rebuttal: 1-2 sentences with a concrete response strategy.",
      "4. Drop edits that are pure stylistic preference, duplicates, or contradict another edit.",
      "5. If two edits touch the same anchor, MERGE them or drop the weaker one.",
      "",
      "═══ INSTRUCTION (for context) ═══",
      active.instruction,
      "",
      "═══ EDITS TO CRITIQUE ═══",
      JSON.stringify(edits, null, 1),
    ].join("\n");
  }

  function _buildProactivePrompt(active) {
    return [
      "You are a senior associate reviewing a contract for issues the client did NOT ask you to address.",
      "Read the doc with fresh eyes. Surface 3-8 things the client should know about, even though they're outside the original instruction.",
      "Examples: missing standard clauses, unfavorable defaults, unusual definitions, asymmetric obligations the client may not have noticed.",
      "Return JSON only.",
      "",
      "OUTPUT SHAPE:",
      "{",
      "  \"unrequested\": [",
      "    {",
      "      \"section\": \"§15 Liability\",",
      "      \"observation\": \"Liability cap is unlimited — your standard form caps at 12 months of fees.\",",
      "      \"severity\": \"high\",",
      "      \"suggestedAction\": \"Add a 12-month fees-paid liability cap.\"",
      "    }",
      "  ]",
      "}",
      "",
      "RULES:",
      "1. severity: 'high' (material business risk), 'medium' (worth knowing), 'low' (FYI).",
