  }

  function _buildNegotiationStrategyPrompt(active, edits) {
    var slim = edits.map(function (e) {
      return { id: e.id, section: e.section, category: e.category, confidence: e.confidence, summary: (e.rationale || "").slice(0, 100) };
    });
    return [
      "You are a senior negotiator. Given the proposed edits below, design a presentation strategy.",
      "Group edits into 2-3 ROUNDS to negotiate sequentially. Round 1 = highest-priority + lowest-pushback. Round 2 = harder asks. Round 3 = nice-to-haves you'd trade.",
      "Return JSON only.",
      "",
      "OUTPUT SHAPE:",
      "{",
      "  \"rationale\": \"1-paragraph explanation of the strategy.\",",
      "  \"rounds\": [",
      "    { \"name\": \"Round 1: Anchors\",   \"editIds\": [\"e1\", \"e3\", \"e7\"], \"why\": \"low-risk wins\" },",
      "    { \"name\": \"Round 2: Substantive\", \"editIds\": [\"e2\", \"e5\"],       \"why\": \"...\" },",
      "    { \"name\": \"Round 3: Trade material\", \"editIds\": [\"e4\", \"e6\"],   \"why\": \"...\" }",
      "  ]",
      "}",
      "",
      "RULES:",
      "1. EVERY edit id must appear in EXACTLY one round.",
      "2. Round 1 should be the largest (low-pushback wins build momentum).",
      "3. `why` is one short sentence per round.",
      "",
      "═══ EDITS ═══",
      JSON.stringify(slim, null, 1),
    ].join("\n");
  }

  // Legacy single-pass prompt — kept for any future fallback path.
  function _buildPlanPromptSync(active, settings) {
    var docPayload = JSON.stringify(active.qaIndex, null, 1);
    var tone = (settings && settings.tone) || "balanced";
    var toneGuide =
      tone === "aggressive"   ? "Take a strong position in favor of the requestor's interests. Push for materially better terms across all in-scope categories. Err on the side of MORE edits, not fewer." :
      tone === "conservative" ? "Make modest, market-standard adjustments only. Avoid edits that would likely be rejected as unreasonable." :
                                "Balanced — propose edits that improve the requestor's position with terms a sophisticated counterparty would likely accept. Err on the side of identifying MORE potential improvements, not fewer.";
    return [
      "You are an associate attorney revising a contract per the client's instruction.",
      "Return ONE JSON object matching the example schema exactly. No prose, no preamble, no markdown fences — just JSON.",
      "",
      "TASK: Read the entire document below, then propose EVERY edit that serves the client's instruction. Be thorough — your job is to surface every relevant change, not just the most obvious one. A typical pass on a 10-page contract should produce 5-15 edits across multiple sections.",
      "",
      "EXAMPLE OUTPUT FORMAT (illustrative — produce edits relevant to YOUR doc + instruction):",
      "{",
      "  \"summary\": \"Tilted payment terms, narrowed indemnity, and added MFN protection in Colgate's favor.\",",
      "  \"edits\": [",
      "    {",
      "      \"id\": \"e1\",",
      "      \"type\": \"replace\",",
      "      \"paragraphId\": \"ELI_QA_14\",",
      "      \"section\": \"§4.2 Payment Terms\",",
      "      \"anchorText\": \"thirty (30) days\",",
      "      \"replacementText\": \"sixty (60) days\",",
      "      \"rationale\": \"Extends Colgate's working-capital cycle.\",",
      "      \"category\": \"payment-terms\",",
      "      \"confidence\": 5,",
      "      \"requiresHumanReview\": false",
      "    },",
      "    {",
      "      \"id\": \"e2\",",
      "      \"type\": \"insert\",",
      "      \"paragraphId\": \"ELI_QA_42\",",
      "      \"section\": \"§11 Most-Favored Nation\",",
      "      \"anchorText\": \"This Agreement shall be governed by\",",
      "      \"replacementText\": \"Hill's shall not offer any third party terms more favorable than those granted to Colgate hereunder without first offering such terms to Colgate.\",",
      "      \"insertPosition\": \"before\",",
      "      \"rationale\": \"Adds standard MFN protection.\",",
      "      \"category\": \"mfn\",",
      "      \"confidence\": 4,",
      "      \"requiresHumanReview\": true",
      "    }",
      "  ]",
      "}",
      "",
      "RULES:",
      "1. `anchorText` MUST be a verbatim text snippet copied from the document below. Pick a UNIQUE phrase (5-15 words usually) so it can be located precisely.",
      "2. `paragraphId` MUST exactly match the `id` field of one of the paragraphs below (e.g., 'ELI_QA_14' or '_eg_p_3').",
      "3. `section` — copy from the paragraph's `section` field if present. Skip if null.",
      "4. Prefer MINIMAL replace edits — change only the words that need to change. For broader rewrites, use multiple smaller edits rather than one giant one.",
      "5. For judgment-heavy spots (asymmetric obligations, scope shifts, removing entire clauses), set `requiresHumanReview: true` and explain trade-offs in the rationale.",
      "6. Confidence (1-5): 5 = standard market move, 4 = reasonable but worth review, 3 = aggressive, 2-1 = unusual/risky.",
      "7. Categories: payment-terms, indemnity, ip, termination, mfn, audit, warranty, confidentiality, dispute-resolution, boilerplate, other.",
      "8. `type` values: 'replace' (modify existing text), 'insert' (add new content positioned relative to anchorText), 'delete' (strike the anchorText entirely).",
      "9. For 'insert', `insertPosition` is 'after' (default) or 'before'.",
      "10. Each edit needs a unique `id` (e1, e2, e3...).",
      "11. If after reading the doc you find NOTHING actionable for the instruction, return `{\"summary\": \"...explain why no edits...\", \"edits\": []}`. But this should be RARE — most legal docs have multiple opportunities for any reasonable instruction.",
      "",
      "TONE: " + toneGuide,
      "",
      "═══ INSTRUCTION ═══",
      active.instruction,
      "",
      "═══ DOCUMENT (paragraph-indexed JSON) ═══",
      docPayload,
    ].join("\n");
  }
  // Validate + normalize the plan returned by the AI. Drops malformed
  // edits (missing required fields) rather than failing the whole plan.
  // Cross-references paragraphId against the qaIndex to:
  //   • infer `section` when the AI omitted it
  //   • compute paragraphIndex (1-based position in doc) for the
  //     "Paragraph N of M" footer line on each card
  function _validatePlan(plan) {
    if (!plan || typeof plan !== "object") {
      return { summary: "", edits: [] };
    }
    var edits = Array.isArray(plan.edits) ? plan.edits : [];
    var validated = [];
    var seenIds = {};
    // Build paragraphId → {section, index1Based} lookup from the qaIndex.
    var qaIndex = (_egActive && _egActive.qaIndex) || [];
    var paraLookup = {};
    qaIndex.forEach(function (p, i) {
      if (p && p.id) paraLookup[p.id] = { section: p.section || null, index: i + 1, text: p.text || "" };
    });
    var totalParas = qaIndex.length;
    edits.forEach(function (e, idx) {
      if (!e || typeof e !== "object") return;
      var id = String(e.id || ("e" + (idx + 1)));
      if (seenIds[id]) id = id + "_" + idx;
      seenIds[id] = true;
      var type = e.type === "insert" || e.type === "delete" ? e.type : "replace";
      var hasAnchor = typeof e.anchorText === "string" && e.anchorText.trim().length > 0;
      if (!hasAnchor) return; // skip malformed
      if (type !== "delete") {
        var hasReplacement = typeof e.replacementText === "string" && e.replacementText.trim().length > 0;
        if (!hasReplacement) return;
      }
      var paraId = typeof e.paragraphId === "string" ? e.paragraphId : null;
      var aiSection = typeof e.section === "string" ? e.section.trim() : "";
      // Section is ALWAYS derived from the structural-map lookup —
      // never from AI. The AI hallucinates section numbers by reading
      // text content of clauses (e.g., a clause that mentions "Section
      // 12" makes the AI label it as Section 12 even though it lives
      // in §3.4). The kernel's structural map is the authoritative
      // source — derived from real Word headings, not text snippets.
      // If the lookup misses (e.g., simple-fallback index with no
      // bookmarks), show null and the UI displays "not identified"
      // rather than risk a wrong number.
      var lookup = paraId ? paraLookup[paraId] : null;
      var lookupSection = lookup && lookup.section ? String(lookup.section).trim() : "";
      var resolvedSection = lookupSection || null;
      // Telemetry — surfaces the discrepancy when AI hallucinates a
      // section number. Useful for monitoring AI behavior.
      if (aiSection && lookupSection && aiSection !== lookupSection) {
        try {
          eli.log.event("tool", "eli_agent_section_mismatch", {
            paragraphId: paraId,
            aiSection: aiSection,
            lookupSection: lookupSection,
          });
        } catch (_) {}
      }
      if (aiSection && !lookupSection) {
        try {
          eli.log.event("tool", "eli_agent_section_unmappable", {
            paragraphId: paraId,
            aiSection: aiSection,  // discarded — but worth knowing what AI guessed
          });
        } catch (_) {}
      }
      validated.push({
        id: id,
        type: type,
        paragraphId: paraId,
        paragraphIndex: lookup ? lookup.index : null,
        paragraphTotal: totalParas || null,
        paragraphText: lookup ? lookup.text : null,  // for inline-redline render
        section: resolvedSection,
        anchorText: e.anchorText,
        replacementText: typeof e.replacementText === "string" ? e.replacementText : null,
        insertPosition: e.insertPosition === "before" ? "before" : "after",
        rationale: typeof e.rationale === "string" ? e.rationale : "",
        category: typeof e.category === "string" ? e.category : "other",
        confidence: Math.max(1, Math.min(5, parseInt(e.confidence, 10) || 3)),
        requiresHumanReview: !!e.requiresHumanReview,
        // Critique-pass enrichment fields. Empty until the critique
        // pass completes; UI conditionally shows them.
        counterargument: typeof e.counterargument === "string" ? e.counterargument : "",
        rebuttal: typeof e.rebuttal === "string" ? e.rebuttal : "",
        bucket: typeof e.bucket === "string" ? e.bucket : null,
        // Email-agent linkage — set by per-comment bucket prompts so
        // the review UI can show "addresses comment c3 from Sarah."
        addressesComment: typeof e.addressesComment === "string" ? e.addressesComment : null,
      });
    });
    return { summary: typeof plan.summary === "string" ? plan.summary : "", edits: validated };
  }
  // Kernel completeJSON schema is a top-level shape map ({key: "type"}),
  // not full JSON Schema. We rely on the prompt to enforce the actual
  // structure, then _validatePlan does deep normalization. The schema
  // here just catches catastrophic shape failures (AI returns a string
  // instead of an object).
  var PLAN_SCHEMA = { summary: "string", edits: "object" };

  // ─── Card scroll-flash (mini-map + strategy pill click) ──────────
  function _flashCard(editId) {
    var el = document.getElementById("_eg_card_" + editId);
    if (!el) return;
    el.scrollIntoView({ behavior: "smooth", block: "center" });
    el.classList.add("_eg_card_flash");
    setTimeout(function () {
      if (el) el.classList.remove("_eg_card_flash");
    }, 1400);
  }

  // ─── Iterative refinement (per-edit re-plan) ──────────────────────
  // 🔥 More aggressive · ❄️ Soften · 🔄 Try a different approach
  // Runs a single AI call against just this edit + the original
  // doc context, replaces the edit in-place. No full re-plan.
  function _refineEdit(edit, mode, btnEl) {
    if (!edit || !_egActive) return;
    var origLabel = btnEl ? btnEl.innerHTML : "";
    if (btnEl) { btnEl.innerHTML = "⚙"; btnEl.disabled = true; }
    var prompt = _buildRefinePrompt(_egActive, edit, mode);
    return _aiJsonCall(prompt, { edit: "object" })
      .then(function (result) {
        if (!result || !result.edit) throw new Error("Empty refinement result");
        // Validate via the same plan-validator (single-edit pass).
        var validated = _validateEdits([result.edit]);
        if (!validated.length) throw new Error("Refinement was malformed");
        var refined = validated[0];
        refined.id = edit.id;  // preserve original id
        refined.bucket = edit.bucket;
        // Splice in.
        var idx = _egActive.plan.edits.findIndex(function (e) { return e.id === edit.id; });
        if (idx !== -1) _egActive.plan.edits[idx] = refined;
        _renderOverlayBody();
        // Flash the refined card so user sees what changed.
        setTimeout(function () { _flashCard(edit.id); }, 50);
      })
      .catch(function (err) {
        if (btnEl) {
          btnEl.innerHTML = "⚠";
          setTimeout(function () {
            if (btnEl) { btnEl.innerHTML = origLabel; btnEl.disabled = false; }
          }, 1400);
        }
        eli.log.event("tool", "eli_agent_refine_failed", { mode: mode, msg: err && err.message });
      });
  }
  function _buildRefinePrompt(active, edit, mode) {
    var modeGuide =
      mode === "aggressive"   ? "Make this edit MORE AGGRESSIVE — push harder for the requestor's interests, even if it raises pushback risk." :
      mode === "soften"       ? "SOFTEN this edit — propose a more market-standard, easier-to-accept version that still serves the original goal." :
                                "Propose a DIFFERENT APPROACH to achieve the same goal — different wording, different structure, different angle. Don't just rephrase.";
    return [
      "You are refining a single proposed contract edit.",
      modeGuide,
      "Return JSON in the SAME shape as the input edit. Add `counterargument` and `rebuttal` if they help.",
      "",
      "OUTPUT SHAPE:",
      "{",
      "  \"edit\": {",
      "    \"type\": \"replace\",",
      "    \"paragraphId\": \"...\", \"section\": \"...\", \"anchorText\": \"...\", \"replacementText\": \"...\",",
      "    \"rationale\": \"...\", \"category\": \"...\", \"confidence\": 4, \"requiresHumanReview\": false,",
      "    \"counterargument\": \"...\", \"rebuttal\": \"...\"",
      "  }",
      "}",
      "",
      "═══ CLIENT'S OVERALL INSTRUCTION ═══",
      active.instruction,
      "",
      "═══ CURRENT EDIT TO REFINE ═══",
      JSON.stringify(edit, null, 1),
      "",
      "═══ DOCUMENT (for context) ═══",
      _docPayload(active),
    ].join("\n");
  }

  // ─── Locate ───────────────────────────────────────────────────────
  // Jumps Word to the edit's anchor — selects the anchor text + scrolls
  // it into view. Tries the bookmark first (precise, paragraph-scoped
  // via ELI_QA_*) then falls back to body-wide searchWithFallback.
  // Brief visual confirmation on the button so the user knows the
  // jump fired even if Word is in a different monitor.
  function _locateEdit(edit, btnEl) {
    if (!edit || !eli.host || typeof eli.host.runRaw !== "function") return;
    var origLabel = btnEl ? btnEl.innerHTML : "";
    if (btnEl) { btnEl.innerHTML = "🔎 Locating…"; btnEl.disabled = true; }
    return eli.host.runRaw("eli_agent:locate", function (context) {
      var doc = context.document;
      // Bookmark first.
      if (edit.paragraphId) {
        var bm = doc.getBookmarkRangeOrNullObject(edit.paragraphId);
        bm.load("isNullObject");
        return context.sync().then(function () {
          if (!bm.isNullObject) {
            return _locateInRange(context, bm, edit);
          }
          return _locateInBody(context, edit);
        });
      }
      return _locateInBody(context, edit);
    }).then(function (result) {
      if (btnEl) {
        btnEl.innerHTML = (result && result.found) ? "✓ Located" : "⚠ Not found";
        setTimeout(function () {
          if (btnEl) { btnEl.innerHTML = origLabel; btnEl.disabled = false; }
        }, 1400);
      }
      eli.log.event("tool", "eli_agent_locate", {
        editId: edit.id,
        found: !!(result && result.found),
        viaBookmark: !!(result && result.viaBookmark),
      });
    }).catch(function (err) {
      if (btnEl) {
        btnEl.innerHTML = "⚠ Error";
        setTimeout(function () {
          if (btnEl) { btnEl.innerHTML = origLabel; btnEl.disabled = false; }
        }, 1400);
      }
      eli.log.event("tool", "eli_agent_locate_failed", { msg: err && err.message });
    });
  }
  function _locateInRange(context, range, edit) {
    var helpers = (eli.host && eli.host.helpers) || {};
    var swfn = helpers.searchWithFallback;
    if (typeof swfn !== "function") {
      // No helper — just select the bookmarked paragraph itself.
      range.select();
      range.scrollIntoView();
      return context.sync().then(function () {
        return { found: true, viaBookmark: true };
      });
    }
    return swfn(range, edit.anchorText, context).then(function (anchorRange) {
      if (anchorRange) {
        anchorRange.select();
        anchorRange.scrollIntoView();
        return context.sync().then(function () {
          return { found: true, viaBookmark: true };
        });
      }
      // Fall back to the bookmarked paragraph itself if anchor missed.
      range.select();
      range.scrollIntoView();
      return context.sync().then(function () {
        return { found: true, viaBookmark: true };
      });
    });
  }
  function _locateInBody(context, edit) {
    var body = context.document.body;
    var helpers = (eli.host && eli.host.helpers) || {};
    var swfn = helpers.searchWithFallback;
    if (typeof swfn !== "function") return Promise.resolve({ found: false });
    return swfn(body, edit.anchorText, context).then(function (anchorRange) {
      if (!anchorRange) return { found: false };
      anchorRange.select();
      anchorRange.scrollIntoView();
      return context.sync().then(function () { return { found: true, viaBookmark: false }; });
    });
  }

  // ─── Apply ────────────────────────────────────────────────────────
  // Walks accepted edits, looks up each paragraph's bookmark range,
  // searches WITHIN that paragraph for the anchor text via host
  // helpers, then applies via insertText/insertParagraph/delete with
  // Track Changes ON. One runRaw per edit so anchoring is fresh each
  // time (Word's Track Changes layer absorbs position drift).
  function _applyAcceptedEdits() {
    if (!_egActive || !_egActive.plan) return;
    var accepted = (_egActive.plan.edits || []).filter(function (e) {
      return _egActive.acceptance[e.id] === "accepted";
    });
    if (!accepted.length) return;
    _egActive.status = "applying";
    _renderOverlayBody();
    var failures = [];
    var applied = 0;
    function _applyOne(edit) {
      return eli.host.runRaw("eli_agent:apply_one", function (context) {
        var doc = context.document;
        try { doc.changeTrackingMode = "TrackAll"; } catch (_e) {}
        // Bookmark-anchored search first (preferred — paragraph-scoped
        // via the ELI_QA_* anchors ask_eli plants on every paragraph).
        // Falls back to body-wide search if the bookmark is missing.
        if (edit.paragraphId) {
          var bm = doc.getBookmarkRangeOrNullObject(edit.paragraphId);
          bm.load("isNullObject");
          return context.sync().then(function () {
            if (bm.isNullObject) return _applyAtBodyScope(context, edit);
            return _applyInRange(context, bm, edit);
          });
        }
        return _applyAtBodyScope(context, edit);
      });
    }
    function _applyInRange(context, range, edit) {
      var helpers = (eli.host && eli.host.helpers) || {};
      var swfn = helpers.searchWithFallback;
      if (typeof swfn !== "function") {
        return Promise.reject(new Error("eli.host.helpers.searchWithFallback unavailable (host:2 required)"));
      }
      // searchWithFallback: third arg is the Word.RequestContext.
      return swfn(range, edit.anchorText, context)
        .then(function (anchorRange) {
          if (!anchorRange) throw new Error("anchor not found in paragraph");
          return _executeEdit(context, anchorRange, edit);
        });
    }
    function _applyAtBodyScope(context, edit) {
      var body = context.document.body;
      var helpers = (eli.host && eli.host.helpers) || {};
      var swfn = helpers.searchWithFallback;
      if (typeof swfn !== "function") {
        return Promise.reject(new Error("eli.host.helpers.searchWithFallback unavailable (host:2 required)"));
      }
      return swfn(body, edit.anchorText, context)
        .then(function (anchorRange) {
          if (!anchorRange) throw new Error("anchor not found in document");
          return _executeEdit(context, anchorRange, edit);
        });
    }
    function _executeEdit(context, anchorRange, edit) {
      var helpers = (eli.host && eli.host.helpers) || {};
      var amfn = helpers.applyMinimalEdit;
      if (edit.type === "delete") {
        anchorRange.delete();
        return context.sync();
      }
      if (edit.type === "insert") {
        // Insert as a new paragraph after (or before) the anchor.
        anchorRange.insertParagraph(edit.replacementText, edit.insertPosition === "before" ? "Before" : "After");
        return context.sync();
      }
      // replace — applyMinimalEdit signature: (range, original, correction, context, opts).
      if (typeof amfn === "function") {
        return amfn(anchorRange, edit.anchorText, edit.replacementText, context, { preserveFormatting: true });
      }
      anchorRange.insertText(edit.replacementText, "Replace");
      return context.sync();
    }
    var appliedEdits = [];  // successful edits — surfaced on _bodyApplied
    function _runChain(idx) {
      if (idx >= accepted.length) {
        _egActive.applyResult = {
          applied: applied,
          failures: failures,
          appliedEdits: appliedEdits,
        };
        _egActive.status = "applied";
        _renderOverlayBody();
        eli.log.event("tool", "eli_agent_apply_complete", {
          agent: _egActive.agent,
          applied: applied,
          failed: failures.length,
        });
        return;
      }
      var edit = accepted[idx];
      _applyOne(edit).then(function () {
        applied++;
        appliedEdits.push(edit);
      }, function (err) {
        failures.push({ edit: edit, reason: (err && err.message) || String(err) });
      }).then(function () {
        _runChain(idx + 1);
      });
    }
    _runChain(0);
  }

  // ─── Manage Agents modal ──────────────────────────────────────────
  // Barebones V1: list every registered agent with an enable toggle
  // and the agent's description. Tone/scope controls render but only
  // tone is editable in V1 (scope checkboxes ship in Phase 2 once the
  // planning prompt actually consumes them).
  function _openManageAgentsModal() {
    _closeManageAgentsModal();
    var modal = document.createElement("div");
    modal.id = "_eg_manage_modal";
    modal.className = "_eg_modal_backdrop";
    modal.innerHTML =
      '<div class="_eg_modal_panel">' +
        '<div class="_eg_modal_header">' +
          '<div class="_eg_modal_title">⚙ Manage Agents</div>' +
          '<button id="_eg_manage_close" type="button" class="_eg_btn_ghost">✕</button>' +
        '</div>' +
        '<div id="_eg_manage_body" class="_eg_modal_body">' +
          '<div style="font-size:11px;color:#64748b;text-align:center;padding:24px;">Loading agents…</div>' +
        '</div>' +
      '</div>';
    document.body.appendChild(modal);
    document.getElementById("_eg_manage_close").onclick = _closeManageAgentsModal;
    modal.onclick = function (ev) { if (ev.target === modal) _closeManageAgentsModal(); };
    _renderManageAgentsBody();
  }
  function _renderManageAgentsBody() {
    var body = document.getElementById("_eg_manage_body");
    if (!body) return;
    Promise.all(AGENT_REGISTRY.map(function (a) {
      return _getAgentSettings(a.id).then(function (s) { return { agent: a, settings: s }; });
    })).then(function (rows) {
      var html = '';
      rows.forEach(function (row) {
        var enabled = row.settings.enabled !== false;
        var tone = row.settings.tone || "balanced";
        html +=
          '<div class="_eg_manage_card">' +
            '<div class="_eg_manage_card_head">' +
              '<div class="_eg_manage_card_title">' +
                '<span style="font-size:18px;">' + _esc(row.agent.icon) + '</span>' +
                '<span>' + _esc(row.agent.displayName) + '</span>' +
              '</div>' +
              '<label class="_eg_toggle">' +
                '<input type="checkbox" data-eg-toggle-agent="' + _esc(row.agent.id) + '"' + (enabled ? ' checked' : '') + '>' +
                '<span>' + (enabled ? 'Enabled' : 'Disabled') + '</span>' +
              '</label>' +
            '</div>' +
            '<div class="_eg_manage_card_desc">' + _esc(row.agent.description) + '</div>' +
            '<div class="_eg_manage_card_settings">' +
              '<label class="_eg_setting_label">Default tone</label>' +
              '<select data-eg-tone="' + _esc(row.agent.id) + '">' +
                '<option value="conservative"' + (tone === "conservative" ? ' selected' : '') + '>Conservative</option>' +
                '<option value="balanced"' + (tone === "balanced" ? ' selected' : '') + '>Balanced</option>' +
                '<option value="aggressive"' + (tone === "aggressive" ? ' selected' : '') + '>Aggressive</option>' +
              '</select>' +
            '</div>' +
          '</div>';
      });
      body.innerHTML = html;
      _wireManageAgentsControls();
    }).catch(function (err) {
      body.innerHTML = '<div style="font-size:11px;color:#991b1b;padding:24px;text-align:center;">Failed to load agents: ' + _esc(err && err.message) + '</div>';
    });
  }
  function _wireManageAgentsControls() {
    document.querySelectorAll("[data-eg-toggle-agent]").forEach(function (cb) {
      cb.onchange = function () {
        var id = cb.getAttribute("data-eg-toggle-agent");
        _getAgentSettings(id).then(function (s) {
          s.enabled = cb.checked;
          return _setAgentSettings(id, s);
        }).then(function () {
          _renderManageAgentsBody();  // refresh enabled-state label
        });
      };
    });
    document.querySelectorAll("[data-eg-tone]").forEach(function (sel) {
      sel.onchange = function () {
        var id = sel.getAttribute("data-eg-tone");
        _getAgentSettings(id).then(function (s) {
          s.tone = sel.value;
          return _setAgentSettings(id, s);
        });
      };
    });
  }
  function _closeManageAgentsModal() {
    var modal = document.getElementById("_eg_manage_modal");
    if (modal && modal.parentNode) modal.parentNode.removeChild(modal);
  }

  // ─── Bus listener: paint dropdown when ask_eli mounts its input ───
  // ask_eli emits 'ask_eli:input_mounted' (additive patch) with
  // { slotEl, sendBtn, inputEl, getQaContext }. We paint into slotEl
  // and mark the send button for label-flip. If ask_eli isn't
  // patched yet (older bundle), this listener simply never fires.
  // Bundle CSS is auto-injected by the kernel from style.css — no
  // manual injection needed.
  if (eli.bus && typeof eli.bus.on === "function") {
    eli.bus.on("ask_eli:input_mounted", function (payload) {
      _paintDropdown(payload);
    });
  }

  // ─── Dispatch handlers ────────────────────────────────────────────
  // intercept_submit: ask_eli calls this BEFORE running its Q&A
  // pipeline. If the current mode isn't "ask_eli", we open the agent
  // overlay and return { handled: true } to short-circuit ask_eli's
  // Q&A path. Returning falsy lets Q&A proceed normally.
  eli.register({
    eli_agent: {
      list_agents: function () { return _listAgents(); },
      get_agent_settings: function (agentId) { return _getAgentSettings(agentId); },
      set_agent_settings: function (payload) {
        if (!payload || !payload.agentId) return Promise.reject(new Error("Missing agentId"));
        return _setAgentSettings(payload.agentId, payload.settings || {});
      },
      intercept_submit: function (payload) {
        if (!_currentMode || _currentMode === "ask_eli") return { handled: false };
        var agentId = _currentMode.replace(/^agent:/, "");
        _openAgentOverlay({
          agent: agentId,
          instruction: (payload && payload.instruction) || "",
          qaIndex: payload && payload.qaIndex,
          docHash: payload && payload.docHash,
        });
        return { handled: true };
      },
      open_agent: function (payload) { _openAgentOverlay(payload || {}); },
      get_current_mode: function () { return _currentMode; },
      set_mode: function (mode) { _setMode(mode); },
    },
    // Tile dispatch for users who pin the Manage Agents UI as a
    // standalone tile (audience controls keep this admin-only).
    tile: {
      app_eli_agent: function () { _openManageAgentsModal(); },
    },
  });

  // ─── Helpers ──────────────────────────────────────────────────────
  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }

  eli.log.event("tool", "eli_agent_initialized", { agentCount: AGENT_REGISTRY.length });
}

jsonTools.css:
/* tools/eli_agent/style.css
   ELI Agent — dropdown trigger, menu, agent overlay, Manage Agents
   modal. Light palette throughout (per CLAUDE.md theme split rule:
   tools + dialogs use light palette in both themes). */

/* ─── Inline caret next to ask_eli title ─── */
/* Sits between "🤖 Ask ELI" text and the index status dot. No
   button chrome — just a small chevron that reads as part of the
   title text. Clicking opens the mode menu. Tints amber when an
   agent mode is active so the user can see at a glance they're
   not in default Q&A mode. */
._eg_caret_inline {
  display: inline-block;
  margin: 0 6px 0 4px;
  font-size: 11px;
  color: currentColor;
  opacity: 0.55;
  cursor: pointer;
  user-select: none;
  vertical-align: middle;
  transition: opacity 0.12s, color 0.12s, transform 0.12s;
}
._eg_caret_inline:hover {
  opacity: 1;
  transform: translateY(1px);
}
._eg_caret_inline._eg_caret_active {
  color: #f59e0b;
  opacity: 1;
}

/* ─── Dropdown menu (floating below trigger) ─── */
._eg_menu_row {
  user-select: none;
  transition: background 0.08s;
}
._eg_menu_row:hover {
  background: #f1f5f9 !important;
}
._eg_menu_row_action {
  font-style: italic;
  color: #475569 !important;
}
._eg_menu_divider {
  height: 1px;
  background: #e2e8f0;
  margin: 4px 0;
}

/* ─── Agent overlay (the panel that opens on Plan Edits) ─── */
._eg_overlay {
  position: fixed;
  top: 80px;
  right: 24px;
  width: 480px;
  height: 520px;
  min-width: 360px;
  min-height: 320px;
  z-index: 99998;
  background: #fff;
  border: 1px solid #cbd5e1;
  box-shadow: 0 16px 48px rgba(15, 23, 42, 0.32);
  font-family: Inter, 'Segoe UI', system-ui, sans-serif;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
._eg_header {
  padding: 11px 14px;
  background: linear-gradient(135deg, #1e3a8a 0%, #1565c0 100%);
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  cursor: move;
  user-select: none;
  flex: 0 0 auto;
}
._eg_header_title {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}
._eg_header_icon {
  font-size: 16px;
  line-height: 1;
}
._eg_header_label {
  font-size: 13px;
  font-weight: 800;
  letter-spacing: 0.02em;
}
._eg_header_actions {
  display: flex;
  gap: 4px;
}
._eg_btn_ghost {
  background: rgba(255, 255, 255, 0.18);
  border: 1px solid rgba(255, 255, 255, 0.4);
  color: #fff;
  padding: 3px 9px;
  font-size: 11px;
  font-weight: 700;
  cursor: pointer;
  border-radius: 0;
  line-height: 1.2;
  transition: background 0.12s;
}
._eg_btn_ghost:hover {
  background: rgba(255, 255, 255, 0.28);
}
._eg_body {
  flex: 1 1 auto;
  overflow-y: auto;
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 14px;
  color: #0f172a;
}
._eg_section_label {
  font: 700 9px/1.2 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.6px;
  color: #64748b;
}
._eg_instruction {
  padding: 10px 12px;
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  border-left: 3px solid #1565c0;
  font-size: 13px;
  line-height: 1.5;
  color: #0f172a;
  white-space: pre-wrap;
}
._eg_context {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 8px 12px;
  background: #fff;
  border: 1px solid #e2e8f0;
  font-family: monospace;
  font-size: 11px;
  color: #475569;
}
._eg_status_box {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 12px;
  background: #fef3c7;
  border: 1px solid #fcd34d;
  font-size: 11px;
  color: #92400e;
  font-weight: 600;
}
._eg_status_dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #f59e0b;
  flex-shrink: 0;
  animation: _eg_pulse 1.6s ease-in-out infinite;
}
@keyframes _eg_pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.45; }
}

/* ─── Review UI: summary, stats, edit cards, diff styling ─── */
._eg_summary {
  font-size: 12px;
  line-height: 1.55;
  color: #0f172a;
  padding: 10px 12px;
  background: #f1f5f9;
  border-left: 3px solid #1565c0;
}
._eg_review_stats {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
  font-size: 10px;
}
._eg_stat {
  padding: 3px 8px;
  font-weight: 700;
  background: #fff;
  border: 1px solid #cbd5e1;
  color: #475569;
}
._eg_stat_accepted { background: #d1fae5; border-color: #6ee7b7; color: #065f46; }
._eg_stat_rejected { background: #fee2e2; border-color: #fca5a5; color: #991b1b; }
._eg_stat_pending  { background: #fef3c7; border-color: #fcd34d; color: #92400e; }

._eg_group {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
._eg_group_header {
  font: 700 10px/1.2 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: #1e3a8a;
  padding: 6px 0 4px;
  border-bottom: 1px solid #cbd5e1;
}
._eg_group_count {
  color: #64748b;
  font-weight: 500;
}

._eg_card {
  background: #fff;
  border: 1px solid #cbd5e1;
  border-left: 3px solid #cbd5e1;
  padding: 10px 12px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  transition: border-color 0.12s, background 0.12s;
}
._eg_card_accepted { border-left-color: #10b981; background: #f0fdf4; }
._eg_card_rejected { border-left-color: #ef4444; background: #fef2f2; opacity: 0.6; }
._eg_card_pending  { border-left-color: #f59e0b; }
._eg_card_review   { border-left-color: #d97706; background: #fffbeb; }

._eg_card_top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
}
._eg_card_meta {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 10px;
  color: #475569;
  flex-wrap: wrap;
}
._eg_type_badge {
  font: 700 9px/1.2 monospace;
  padding: 2px 5px;
  border-radius: 2px;
  letter-spacing: 0.5px;
}
._eg_type_replace { background: #dbeafe; color: #1e3a8a; }
._eg_type_insert  { background: #d1fae5; color: #065f46; }
._eg_type_delete  { background: #fee2e2; color: #991b1b; }
._eg_card_section {
  font-weight: 600;
  color: #0f172a;
}
._eg_card_category {
  font-family: monospace;
  font-size: 9px;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  background: #f1f5f9;
  border: 1px solid #e2e8f0;
  padding: 2px 6px;
  color: #475569;
  border-radius: 2px;
}
/* Location header — section title + paragraph index — at the top of
   each card so the user knows WHERE in the doc the edit lands before
   reading the diff. */
._eg_card_loc {
  display: flex;
  flex-direction: column;
  gap: 1px;
  padding: 4px 8px;
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  border-left: 3px solid #1565c0;
  margin-bottom: 2px;
}
._eg_card_loc_section {
  font-size: 11px;
  font-weight: 700;
  color: #0f172a;
  line-height: 1.3;
}
._eg_card_loc_unknown {
  color: #94a3b8;
  font-weight: 500;
  font-style: italic;
}
._eg_card_loc_para {
  font-size: 10px;
  color: #64748b;
  font-family: monospace;
  line-height: 1.3;
}
._eg_card_dots {
  font-family: monospace;
  font-size: 11px;
  color: #1565c0;
  letter-spacing: -1px;
}
._eg_card_review_pill {
  font: 700 9px/1.2 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  background: #fef3c7;
  color: #92400e;
  padding: 2px 6px;
  border-radius: 2px;
}

._eg_card_diff {
  font-family: Georgia, serif;
  font-size: 12px;
  line-height: 1.5;
  color: #0f172a;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
._eg_diff_orig {
  background: #fee2e2;
  padding: 6px 8px;
  border-left: 2px solid #ef4444;
}
._eg_diff_orig del {
  color: #991b1b;
  text-decoration: line-through;
}
._eg_diff_orig._eg_diff_insert_anchor {
  background: #f1f5f9;
  border-left-color: #94a3b8;
  font-size: 10px;
  font-style: italic;
  color: #475569;
  font-family: 'Inter', sans-serif;
}
._eg_diff_new {
  background: #d1fae5;
  padding: 6px 8px;
  border-left: 2px solid #10b981;
}
._eg_diff_new ins {
  color: #065f46;
  text-decoration: none;
  font-weight: 600;
}

._eg_card_rationale {
  font-size: 11px;
  color: #475569;
  font-style: italic;
  line-height: 1.4;
  padding: 4px 0 0;
  border-top: 1px dashed #e2e8f0;
}
._eg_card_actions {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
}
._eg_card_btn {
  font: 600 10px/1.2 'Inter', sans-serif;
  padding: 5px 10px;
  border: 1px solid #cbd5e1;
  background: #fff;
  color: #0f172a;
  cursor: pointer;
  border-radius: 0;
  transition: background 0.1s, border-color 0.1s;
}
._eg_card_btn:hover:not(:disabled) {
  background: #f1f5f9;
  border-color: #94a3b8;
}
._eg_card_btn:disabled {
  opacity: 0.5;
  cursor: default;
}
._eg_card_accept {
  background: #ecfdf5;
  color: #065f46;
  border-color: #6ee7b7;
}
._eg_card_accept:hover:not(:disabled) { background: #d1fae5; }
._eg_card_reject {
  background: #fef2f2;
  color: #991b1b;
  border-color: #fca5a5;
}
._eg_card_reject:hover:not(:disabled) { background: #fee2e2; }
._eg_card_undo {
  background: #fff;
  color: #475569;
}
/* Locate button — neutral blue, sits at the front of the action row
   so the user can preview WHERE an edit will land before accepting. */
._eg_card_locate {
  background: #eff6ff;
  color: #1e3a8a;
  border-color: #93c5fd;
  margin-right: auto;  /* push the accept/reject group to the right */
}
._eg_card_locate:hover:not(:disabled) {
  background: #dbeafe;
  border-color: #60a5fa;
}

/* Sticky bottom action row in the review view. */
._eg_actions_row {
  display: flex;
  gap: 8px;
  padding: 10px 0 4px;
  flex-wrap: wrap;
  align-items: center;
}
._eg_actions_sticky {
  position: sticky;
  bottom: -16px;
  margin: 4px -16px -16px;
  padding: 12px 16px;
  background: #fff;
  border-top: 1px solid #cbd5e1;
  z-index: 5;
}
._eg_btn_primary {
  font: 700 11px/1.2 'Inter', sans-serif;
  padding: 7px 14px;
  background: linear-gradient(135deg, #1565c0 0%, #0d47a1 100%);
  color: #fff;
  border: 1px solid #0d47a1;
  cursor: pointer;
  border-radius: 0;
  transition: transform 0.12s, box-shadow 0.12s;
}
._eg_btn_primary:hover:not(:disabled) {
  transform: translateY(-1px);
  box-shadow: 0 3px 10px rgba(21,101,192,0.28);
}
._eg_btn_primary:disabled { opacity: 0.5; cursor: default; }
._eg_btn_apply {
  margin-left: auto;
}
._eg_btn_secondary {
  font: 600 10px/1.2 'Inter', sans-serif;
  padding: 6px 12px;
  background: linear-gradient(180deg, #f8fafc 0%, #e2e8f0 100%);
  border: 1px solid #cbd5e1;
  color: #0f172a;
  cursor: pointer;
  border-radius: 0;
}
._eg_btn_secondary:hover { background: linear-gradient(180deg, #f1f5f9 0%, #cbd5e1 100%); }

/* Empty / error / applied states. */
._eg_empty_box {
  padding: 24px;
  text-align: center;
  background: #f8fafc;
  border: 1px dashed #cbd5e1;
}
._eg_empty_title {
  font-size: 13px;
  font-weight: 700;
  color: #0f172a;
  margin-bottom: 6px;
}
._eg_empty_msg {
  font-size: 11px;
  color: #64748b;
  line-height: 1.5;
}
._eg_error_box {
  padding: 14px 16px;
  background: #fef2f2;
  border: 1px solid #fca5a5;
  border-left: 3px solid #ef4444;
}
._eg_error_title {
  font-size: 12px;
  font-weight: 700;
  color: #991b1b;
  margin-bottom: 4px;
}
._eg_error_msg {
  font-size: 11px;
  color: #7f1d1d;
  line-height: 1.5;
  word-wrap: break-word;
}
._eg_applied_box {
  padding: 14px 16px;
  background: #d1fae5;
  border: 1px solid #6ee7b7;
  border-left: 3px solid #10b981;
}
._eg_applied_title {
  font-size: 13px;
  font-weight: 800;
  color: #065f46;
  margin-bottom: 4px;
}
._eg_applied_sub {
  font-size: 11px;
  color: #047857;
  line-height: 1.5;
}
._eg_fail_card {
  padding: 8px 12px;
  background: #fef2f2;
  border-left: 3px solid #ef4444;
  margin-bottom: 6px;
}
/* Applied-edit summary rows on the final page. Compact (no decisions
   to make here, just confirmation + locate). */
._eg_applied_row {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 6px 10px;
  padding: 8px 10px;
  background: #f0fdf4;
  border: 1px solid #bbf7d0;
  border-left: 3px solid #10b981;
  margin-bottom: 6px;
  align-items: center;
}
._eg_applied_meta {
  grid-column: 1;
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 10px;
  color: #475569;
}
._eg_applied_para {
  font-family: monospace;
  color: #64748b;
}
._eg_applied_change {
  grid-column: 1;
  font-family: Georgia, serif;
  font-size: 12px;
  line-height: 1.5;
  color: #0f172a;
  word-wrap: break-word;
}
._eg_applied_inserts {
  color: #065f46;
  font-weight: 600;
}
._eg_applied_locate {
  grid-column: 2;
  grid-row: 1 / 3;
  align-self: center;
}
._eg_fail_reason {
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  color: #991b1b;
  margin-bottom: 4px;
}
._eg_fail_text {
  font-size: 11px;
  color: #7f1d1d;
  font-family: Georgia, serif;
  line-height: 1.4;
  word-wrap: break-word;
}

/* ─── Stage strip (5-stage pipeline progress) ─── */
._eg_stage_strip {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 8px 0 4px;
  margin-bottom: 4px;
}
._eg_stage_dot {
  display: flex;
  align-items: center;
  gap: 4px;
  flex: 0 0 auto;
}
._eg_stage_pip {
  display: inline-block;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #e2e8f0;
  border: 1px solid #cbd5e1;
}
._eg_stage_done ._eg_stage_pip {
  background: #10b981;
  border-color: #059669;
}
._eg_stage_active ._eg_stage_pip {
  background: #f59e0b;
  border-color: #d97706;
  animation: _eg_pulse 1.6s ease-in-out infinite;
}
._eg_stage_label {
  font: 600 9px/1 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  color: #94a3b8;
}
._eg_stage_done ._eg_stage_label  { color: #065f46; }
._eg_stage_active ._eg_stage_label { color: #92400e; font-weight: 700; }
._eg_stage_sep {
  flex: 1 1 auto;
  height: 1px;
  background: #e2e8f0;
}

/* ─── Buckets list (Stage 3 progress) ─── */
._eg_bucket_list {
  display: flex;
  flex-direction: column;
  gap: 6px;
}
._eg_bucket_row {
  display: grid;
  grid-template-columns: 24px 1fr auto;
  grid-template-rows: auto auto;
  gap: 2px 8px;
  padding: 8px 10px;
  background: #fff;
  border: 1px solid #cbd5e1;
  border-left: 3px solid #cbd5e1;
  font-size: 11px;
  align-items: center;
}
._eg_bucket_running { border-left-color: #f59e0b; background: #fffbeb; }
._eg_bucket_done    { border-left-color: #10b981; background: #f0fdf4; }
._eg_bucket_failed  { border-left-color: #ef4444; background: #fef2f2; }
._eg_bucket_icon {
  grid-row: 1 / 3;
  text-align: center;
  font-size: 14px;
  font-weight: 700;
  color: #475569;
}
._eg_bucket_running ._eg_bucket_icon {
  color: #d97706;
  animation: _eg_pulse 1.4s ease-in-out infinite;
}
._eg_bucket_done ._eg_bucket_icon   { color: #059669; }
._eg_bucket_failed ._eg_bucket_icon { color: #dc2626; }
._eg_bucket_name {
  grid-column: 2;
  grid-row: 1;
  font-weight: 700;
  color: #0f172a;
}
._eg_bucket_focus {
  grid-column: 2;
  grid-row: 2;
  color: #64748b;
  font-size: 10px;
  line-height: 1.4;
}
._eg_bucket_count {
  grid-column: 3;
  grid-row: 1 / 3;
  font: 700 10px/1.2 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  color: #475569;
  white-space: nowrap;
  text-align: right;
}

/* ─── Negotiation strategy panel (collapsible) ─── */
._eg_strat_panel {
  background: #fff;
  border: 1px solid #1565c0;
  border-left: 4px solid #1565c0;
  margin: 8px 0;
}
._eg_strat_summary {
  font: 700 11px/1.2 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  padding: 10px 12px;
  background: #eff6ff;
  cursor: pointer;
  color: #1e3a8a;
  user-select: none;
}
._eg_strat_panel[open] ._eg_strat_summary { border-bottom: 1px solid #cbd5e1; }
._eg_strat_rationale {
  font-size: 11px;
  line-height: 1.5;
  padding: 10px 12px;
  color: #475569;
  background: #f8fafc;
  border-bottom: 1px dashed #e2e8f0;
}
._eg_strat_round {
  padding: 10px 12px;
  border-bottom: 1px solid #f1f5f9;
}
._eg_strat_round:last-child { border-bottom: none; }
._eg_strat_round_head {
  font-weight: 700;
  font-size: 11px;
  color: #0f172a;
  margin-bottom: 4px;
}
._eg_strat_why {
  font-size: 10px;
  color: #64748b;
  font-style: italic;
  margin-bottom: 6px;
}
._eg_strat_pills {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
}
._eg_strat_pill {
  display: inline-block;
  padding: 3px 8px;
  font: 600 10px/1.2 'Inter', sans-serif;
  background: #dbeafe;
  border: 1px solid #93c5fd;
  color: #1e3a8a;
  cursor: pointer;
  border-radius: 2px;
  transition: background 0.1s, transform 0.1s;
}
._eg_strat_pill:hover {
  background: #bfdbfe;
  transform: translateY(-1px);
}

/* ─── Unrequested findings panel (collapsible) ─── */
._eg_un_panel {
  background: #fff;
  border: 1px solid #d97706;
  border-left: 4px solid #d97706;
  margin: 8px 0;
}
._eg_un_summary {
  font: 700 11px/1.2 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  padding: 10px 12px;
  background: #fffbeb;
  cursor: pointer;
  color: #92400e;
  user-select: none;
}
._eg_un_panel[open] ._eg_un_summary { border-bottom: 1px solid #cbd5e1; }
._eg_un_card {
  padding: 10px 12px;
  border-bottom: 1px solid #f1f5f9;
}
._eg_un_card:last-child { border-bottom: none; }
._eg_un_high { background: #fef2f2; }
._eg_un_med  { background: #fffbeb; }
._eg_un_low  { background: #f8fafc; }
._eg_un_head {
  display: flex;
  gap: 8px;
  align-items: center;
  margin-bottom: 4px;
}
._eg_un_sev {
  font: 700 9px/1.2 monospace;
  letter-spacing: 0.4px;
  padding: 2px 6px;
  background: #fff;
  border: 1px solid #cbd5e1;
  color: #475569;
}
._eg_un_high ._eg_un_sev { color: #991b1b; border-color: #fca5a5; }
._eg_un_low ._eg_un_sev  { color: #64748b; }
._eg_un_section {
  font-weight: 600;
  font-size: 11px;
  color: #0f172a;
}
._eg_un_observation {
  font-size: 12px;
  line-height: 1.5;
  color: #0f172a;
  margin-bottom: 4px;
}
._eg_un_action {
  font-size: 11px;
  color: #475569;
  font-style: italic;
}

/* ─── Mini-map sidebar (right edge of review) ─── */
._eg_review_main {
  display: flex;
  gap: 8px;
}
._eg_cards_col {
  flex: 1 1 auto;
  display: flex;
  flex-direction: column;
  gap: 14px;
  min-width: 0;
}
._eg_minimap {
  flex: 0 0 18px;
  position: relative;
}
._eg_mm_track {
  position: sticky;
  top: 8px;
  width: 18px;
  height: calc(100vh - 220px);
  min-height: 200px;
  background: #f1f5f9;
  border: 1px solid #cbd5e1;
  border-radius: 9px;
}
._eg_mm_pin {
  position: absolute;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 12px;
  height: 12px;
  border-radius: 50%;
  border: 1px solid #475569;
  background: #94a3b8;
  cursor: pointer;
  padding: 0;
  transition: transform 0.1s, box-shadow 0.1s;
}
._eg_mm_pin:hover {
  transform: translate(-50%, -50%) scale(1.4);
  box-shadow: 0 0 0 3px rgba(245,158,11,0.3);
}
._eg_mm_accepted { background: #10b981; border-color: #065f46; }
._eg_mm_rejected { background: #ef4444; border-color: #991b1b; opacity: 0.5; }
._eg_mm_pending  { background: #f59e0b; border-color: #d97706; }
._eg_mm_review { box-shadow: 0 0 0 2px #fcd34d; }

/* ─── Inline redline (Word-style) ─── */
._eg_inline_diff {
  background: #fff;
  padding: 10px 12px;
  border: 1px solid #e2e8f0;
  border-left: 3px solid #1565c0;
  font-family: Georgia, serif;
  font-size: 12px;
  line-height: 1.6;
  color: #0f172a;
  word-wrap: break-word;
}
._eg_inline_del {
  color: #991b1b;
  text-decoration: line-through;
  text-decoration-color: #ef4444;
  background: #fee2e2;
  padding: 0 2px;
}
._eg_inline_ins {
  color: #065f46;
  background: #d1fae5;
  text-decoration: underline;
  text-decoration-color: #10b981;
  font-weight: 600;
  padding: 0 2px;
  margin-left: 2px;
}

/* ─── Refine buttons (per-card iterative refinement) ─── */
._eg_card_refine {
  background: #fef3c7;
  color: #92400e;
  border-color: #fcd34d;
  padding: 5px 8px;
  font-size: 13px;
}
._eg_card_refine:hover:not(:disabled) {
  background: #fde68a;
  border-color: #f59e0b;
}

/* ─── Negotiation prep block (per-card collapsible) ─── */
._eg_card_negprep {
  font-size: 11px;
  border: 1px dashed #93c5fd;
  background: #eff6ff;
  padding: 0;
}
._eg_card_negprep summary {
  font: 700 10px/1.2 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  color: #1e3a8a;
  padding: 6px 8px;
  cursor: pointer;
  user-select: none;
}
._eg_card_negprep[open] summary { border-bottom: 1px solid #bfdbfe; }
._eg_negprep_row {
  padding: 6px 8px;
  line-height: 1.5;
  color: #0f172a;
}
._eg_negprep_label {
  font-weight: 700;
  color: #475569;
  font-family: monospace;
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  margin-right: 4px;
}
._eg_negprep_rebuttal { background: #f8fafc; }

/* ─── Card flash (mini-map + strategy pill scroll target) ─── */
@keyframes _eg_flash_anim {
  0%   { background: #fef3c7; box-shadow: 0 0 0 4px #f59e0b; }
  100% { background: transparent; box-shadow: none; }
}
._eg_card_flash {
  animation: _eg_flash_anim 1.4s ease-out;
}

/* ─── Email-to-Redline: compose pane + confirm + response email ─── */
._eg_compose_hint {
  font-size: 11px;
  color: #475569;
  line-height: 1.5;
  padding: 4px 0 8px;
}
._eg_compose_method {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 10px 12px;
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  border-left: 3px solid #1565c0;
}
._eg_compose_method_head {
  font: 700 10px/1.2 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  color: #475569;
}
._eg_compose_meta {
  font-size: 11px;
  color: #64748b;
  margin-left: 8px;
}
._eg_compose_textarea {
  width: 100%;
  padding: 10px 12px;
  border: 1px solid #cbd5e1;
  font-family: monospace;
  font-size: 11px;
  line-height: 1.5;
  background: #fff;
  color: #0f172a;
  resize: vertical;
  min-height: 100px;
  border-radius: 0;
  outline: none;
  transition: border-color 0.15s, box-shadow 0.15s;
}
._eg_compose_textarea:focus {
  border-color: #1565c0;
  box-shadow: 0 0 0 2px rgba(21,101,192,0.18);
}
._eg_drop_zone {
  border: 2px dashed #cbd5e1;
  background: #fff;
  padding: 18px 12px;
  text-align: center;
  font-size: 11px;
  color: #64748b;
  cursor: pointer;
  transition: border-color 0.15s, background 0.15s;
}
._eg_drop_zone._eg_drop_active {
  border-color: #1565c0;
  background: #eff6ff;
  color: #1e3a8a;
}
._eg_link_btn {
  background: none;
  border: none;
  color: #1565c0;
  text-decoration: underline;
  cursor: pointer;
  font: inherit;
  padding: 0;
}
._eg_comment_row {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 10px 12px;
  background: #fff;
  border: 1px solid #cbd5e1;
  border-left: 3px solid #1565c0;
  margin-bottom: 6px;
}
._eg_comment_skipped {
  opacity: 0.55;
  border-left-color: #94a3b8;
}
._eg_comment_head {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  font-size: 10px;
  color: #475569;
}
._eg_comment_toggle {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-weight: 700;
  cursor: pointer;
  user-select: none;
}
._eg_comment_sev {
  font: 700 9px/1.2 monospace;
  letter-spacing: 0.4px;
  padding: 2px 6px;
  background: #f1f5f9;
  border: 1px solid #cbd5e1;
}
._eg_comment_sev_high     { background: #fee2e2; border-color: #fca5a5; color: #991b1b; }
._eg_comment_sev_must-fix { background: #fee2e2; border-color: #fca5a5; color: #991b1b; }
._eg_comment_sev_med      { background: #fef3c7; border-color: #fcd34d; color: #92400e; }
._eg_comment_sev_low      { background: #f1f5f9; color: #64748b; }
._eg_comment_sev_nit      { background: #f1f5f9; color: #64748b; }
._eg_comment_author {
  font-weight: 700;
  color: #0f172a;
}
._eg_comment_scope {
  color: #1e3a8a;
  font-weight: 600;
}
._eg_comment_ask {
  font-size: 12px;
  line-height: 1.5;
  color: #0f172a;
}
._eg_comment_orig {
  font-size: 10px;
  color: #475569;
  background: #f8fafc;
  padding: 0;
  border: 1px dashed #e2e8f0;
}
._eg_comment_orig summary {
  padding: 4px 8px;
  cursor: pointer;
  user-select: none;
  font-weight: 600;
}
._eg_comment_orig div {
  padding: 6px 8px;
  font-style: italic;
  border-top: 1px dashed #e2e8f0;
}
/* Comment-link pill on edit cards (email-agent provenance trace) */
._eg_card_comment_link {
  font-size: 10px;
  color: #1e3a8a;
  background: #eff6ff;
  border: 1px solid #bfdbfe;
  padding: 4px 8px;
  border-radius: 2px;
  font-style: italic;
  line-height: 1.4;
  cursor: help;
}

/* ─── Draft Agreement: interview pane ─── */
._eg_iv_thread {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-bottom: 8px;
}
._eg_iv_turn {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 8px 12px;
  border-radius: 2px;
}
._eg_iv_user {
  background: #eff6ff;
  border-left: 3px solid #1565c0;
  align-self: flex-end;
  max-width: 88%;
}
._eg_iv_agent {
  background: #f8fafc;
  border-left: 3px solid #94a3b8;
  align-self: flex-start;
  max-width: 88%;
}
._eg_iv_role {
  font: 700 9px/1 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: #64748b;
}
._eg_iv_text {
  font-size: 12px;
  line-height: 1.5;
  color: #0f172a;
  white-space: pre-wrap;
}
._eg_iv_choices {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  padding: 8px 0;
}
._eg_iv_choice_btn {
  flex: 0 0 auto;
}
._eg_iv_input_row {
  display: flex;
  gap: 6px;
  padding: 6px 0;
}
._eg_iv_text_input {
  flex: 1 1 auto;
  padding: 8px 10px;
  border: 1px solid #cbd5e1;
  font-size: 12px;
  font-family: inherit;
  background: #fff;
  color: #0f172a;
  border-radius: 0;
  outline: none;
  transition: border-color 0.15s, box-shadow 0.15s;
}
._eg_iv_text_input:focus {
  border-color: #1565c0;
  box-shadow: 0 0 0 2px rgba(21,101,192,0.18);
}

/* Draft outline review */
._eg_outline_row {
  display: flex;
  gap: 12px;
  padding: 10px 12px;
  background: #fff;
  border: 1px solid #cbd5e1;
  border-left: 3px solid #1565c0;
  margin-bottom: 4px;
  align-items: flex-start;
}
._eg_outline_num {
  font: 700 13px/1.2 monospace;
  color: #1e3a8a;
  flex-shrink: 0;
  width: 36px;
}
._eg_outline_name {
  font-weight: 700;
  color: #0f172a;
  font-size: 12px;
}
._eg_outline_focus {
  font-size: 10px;
  color: #64748b;
  line-height: 1.4;
  margin-top: 2px;
}

/* Draft section review cards */
._eg_draft_section {
  background: #fff;
  border: 1px solid #cbd5e1;
  border-left: 3px solid #10b981;
  margin-bottom: 10px;
}
._eg_draft_section_skip {
  border-left-color: #ef4444;
  opacity: 0.55;
}
._eg_draft_section_head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
  padding: 10px 12px;
  background: #f8fafc;
  border-bottom: 1px solid #e2e8f0;
}
._eg_draft_section_title {
  font-weight: 700;
  color: #0f172a;
  font-size: 12px;
}
._eg_draft_section_actions {
  display: flex;
  gap: 4px;
}
._eg_draft_regen {
  background: #fef3c7;
  color: #92400e;
  border-color: #fcd34d;
}
._eg_draft_preview {
  margin: 0;
  padding: 12px 14px;
  font-family: Georgia, serif;
  font-size: 12px;
  line-height: 1.6;
  color: #0f172a;
  white-space: pre-wrap;
  max-height: 320px;
  overflow-y: auto;
  background: #fff;
}

/* ─── Manage Agents modal ─── */
._eg_modal_backdrop {
  position: fixed;
  inset: 0;
  z-index: 99999;
  background: rgba(15, 23, 42, 0.55);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: Inter, 'Segoe UI', system-ui, sans-serif;
}
._eg_modal_panel {
  background: #fff;
  width: min(640px, 92vw);
  max-height: min(720px, 88vh);
  display: flex;
  flex-direction: column;
  box-shadow: 0 24px 60px rgba(0, 0, 0, 0.4);
  border: 1px solid #cbd5e1;
  overflow: hidden;
}
._eg_modal_header {
  padding: 11px 14px;
  background: linear-gradient(135deg, #1e3a8a 0%, #1565c0 100%);
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  flex: 0 0 auto;
}
._eg_modal_title {
  font-size: 13px;
  font-weight: 800;
  letter-spacing: 0.02em;
}
._eg_modal_body {
  flex: 1 1 auto;
  overflow-y: auto;
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  background: #f8fafc;
}
._eg_manage_card {
  background: #fff;
  border: 1px solid #cbd5e1;
  padding: 14px 16px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
._eg_manage_card_head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}
._eg_manage_card_title {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 13px;
  font-weight: 700;
  color: #0f172a;
}
._eg_manage_card_desc {
  font-size: 11px;
  color: #475569;
  line-height: 1.5;
}
._eg_manage_card_settings {
  display: flex;
  align-items: center;
  gap: 8px;
  padding-top: 8px;
  border-top: 1px dashed #e2e8f0;
}
._eg_setting_label {
  font: 600 10px/1.2 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  color: #64748b;
}
._eg_manage_card_settings select {
  padding: 5px 8px;
  font-size: 11px;
  font-family: inherit;
  border: 1px solid #cbd5e1;
  background: #fff;
  border-radius: 0;
  cursor: pointer;
  color: #0f172a;
}
._eg_toggle {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  font-weight: 600;
  color: #475569;
  cursor: pointer;
  user-select: none;
}
._eg_toggle input[type="checkbox"] {
  cursor: pointer;
  margin: 0;
}
